def test_site_policy_overrides_parse_rate_limits() -> None:
    config = {
        "PTCLI": {
            "SITE_POLICIES": {
                "U2": {
                    "allow_auto_download": True,
                    "allow_retorrent": True,
                    "download_rate_limit": "20MiB/s",
                    "min_seed_time_hours": 72,
                    "rule_review_fingerprint": "u2-review",
                },
                "MTEAM": {
                    "allow_auto_upload": True,
                    "allow_retorrent": True,
                    "upload_rate_limit": "2 MiB/s",
                    "download_rate_limit": "20MiB/s",
                    "min_seed_time_hours": 72,
                    "min_ratio": 1.5,
                    "freeleech_required": True,
                    "required_promotions": ["free"],
                    "forbidden_title_patterns": ["禁转"],
                    "forbidden_release_groups": ["BADGRP"],
                    "rule_review_fingerprint": "mteam-review",
                }
            }
        }
    }

    policy = build_site_policy(config, "MTEAM")
    report = build_site_policy_report(config, ["U2", "MTEAM"], accept_rules=True)

    assert parse_rate_limit("500 KiB/s") == 500 * 1024
    assert policy.upload_rate_limit == 2 * 1024 * 1024
    assert policy.download_rate_limit == 20 * 1024 * 1024
    assert policy.min_seed_time_hours == 72
    assert policy.min_ratio == 1.5
    assert policy.freeleech_required is True
    assert policy.required_promotions == ("free",)
    assert policy.forbidden_title_patterns == ("禁转",)
    assert policy.forbidden_release_groups == ("BADGRP",)
    assert policy.to_dict()["transfer_rules"]["forbidden_release_groups"] == ["BADGRP"]
    assert report["ready"] is True
    assert report["qbit_limits"]["MTEAM"]["upload_limit"] == 2 * 1024 * 1024


def test_site_policy_accepts_structured_config_shape() -> None:
    config = {
        "PTCLI": {
            "SITE_POLICIES": {
                "U2": {
                    "automation": {"download": True, "retorrent": True},
                    "qbit_limits": {"download_limit": "20MiB/s", "upload_limit": "500KiB/s"},
                    "seeding_requirements": {"min_seed_time_hours": 72},
                    "transfer_rules": {"required_promotions": ["free"], "forbidden_release_groups": ["BADGRP"]},
                    "rule_review_fingerprint": "u2-review",
                },
                "MTEAM": {
                    "automation": {"upload": True, "retorrent": True},
                    "qbit_limits": {"upload_limit": "2MiB/s"},
                    "seeding_requirements": {"min_ratio": 1.0},
                    "transfer_rules": {"freeleech_required": True, "forbidden_title_patterns": ["Forbidden"]},
                    "rule_review_fingerprint": "mteam-review",
                },
            }
        }
    }

    u2 = build_site_policy(config, "U2")
    mteam = build_site_policy(config, "MTEAM")
    report = build_site_policy_report(config, ["U2", "MTEAM"], accept_rules=True)

    assert u2.allow_auto_download is True
    assert u2.allow_retorrent is True
    assert u2.download_rate_limit == 20 * 1024 * 1024
    assert u2.upload_rate_limit == 500 * 1024
    assert u2.min_seed_time_hours == 72
    assert u2.required_promotions == ("free",)
    assert u2.forbidden_release_groups == ("BADGRP",)
    assert mteam.allow_auto_upload is True
    assert mteam.upload_rate_limit == 2 * 1024 * 1024
    assert mteam.min_ratio == 1.0
    assert mteam.freeleech_required is True
    assert mteam.forbidden_title_patterns == ("Forbidden",)
    assert report["ready"] is True
    assert report["qbit_limits"]["U2"]["download_limit"] == 20 * 1024 * 1024
    assert report["qbit_limits"]["MTEAM"]["upload_limit"] == 2 * 1024 * 1024


def test_example_config_includes_safe_ptcli_site_policy_templates() -> None:
    namespace = runpy.run_path(str(Path(__file__).resolve().parents[2] / "data" / "example-config.py"))
    config = namespace["config"]
    policies = config["PTCLI"]["SITE_POLICIES"]

    assert {"U2", "CHD", "MTEAM"}.issubset(policies)
    assert policies["U2"]["allow_auto_download"] is True
    assert policies["CHD"]["allow_retorrent"] is True
    assert policies["MTEAM"]["allow_auto_upload"] is True
    assert policies["U2"]["rule_review_fingerprint"] == ""
    assert policies["CHD"]["rule_review_fingerprint"] == ""
    assert policies["MTEAM"]["rule_review_fingerprint"] == ""

    report = build_site_policy_report(config, ["U2", "MTEAM"], accept_rules=True)

    assert report["ready"] is False
    obligations = {policy["tracker"]: policy["rule_obligations"] for policy in report["site_policies"]}
    assert obligations["U2"]["missing_fields"] == ["rule_review_fingerprint"]
    assert obligations["MTEAM"]["missing_fields"] == ["rule_review_fingerprint"]
    assert report["qbit_limits"]["U2"]["download_limit"] == 20 * 1024 * 1024
    assert report["qbit_limits"]["MTEAM"]["upload_limit"] == 2 * 1024 * 1024


