    args = parser.parse_args(["retorrent", "--from", "U2", "--source-id", "60635", "--to", "MTEAM", "--dry-run"])

    plan = build_plan(args)

    assert plan.rule_check["ready"] is False
    assert plan.rule_check["source_tracker"] == "U2"
