def test_summary_check_blocks_pipeline_live_source_injection_without_save_path(tmp_path, capsys) -> None:
    summary_file = tmp_path / "ptcli-run-summary.json"
    pipeline_argv = [
        "python3",
        "ptcli.py",
        "pipeline",
        "--from",
        "U2",
        "--source-id",
        "60635",
        "--to",
        "MTEAM",
        "--upload-target",
        "--target-execute",
        "--confirm-upload",
        "--json",
    ]
    summary_file.write_text(
        json.dumps(
            {
                "schema_version": 1,
                "kind": "ptcli.pipeline.run_summary",
                "ready": False,
                "complete": False,
                "blockers": ["source.ready"],
                "resume_commands": [{"stage": "pipeline-live", "command": shlex.join(pipeline_argv), "argv": pipeline_argv}],
                "resume_state": {
                    "next_stage": "pipeline-live",
                    "next_command": shlex.join(pipeline_argv),
                    "next_command_argv": pipeline_argv,
                    "artifacts": {
                        "target_hash_consistent": True,
                        "target_duplicate_clean": True,
                        "target_rule_obligations": True,
                        "target_preparation_ready": True,
                    },
                },
            }
        ),
        encoding="utf-8",
    )

    code = main(["summary-check", "--summary-file", str(summary_file), "--json"])

    assert code == 1
    payload = json.loads(capsys.readouterr().out)
    assert payload["automation_action"] == "complete_source_command"
    assert payload["next_stage"] == "pipeline-live"
    assert payload["next_command_run_allowed"] is False
    assert payload["next_command_run_blocker"] == "pipeline source injection requires --save-path before automatic execution"
    assert payload["candidate_commands"][0]["run_allowed"] is False
    assert payload["candidate_commands"][0]["run_blocker"] == "pipeline source injection requires --save-path before automatic execution"
    assert payload["rejected_command_blockers"] == ["pipeline source injection requires --save-path before automatic execution"]
    assert payload["source_command_recovery"] == {
        "present": True,
        "missing": ["source_save_path"],
        "required_flags": ["--save-path"],
        "example_flag": "--save-path /downloads",
        "next_actions": ["Add --save-path pointing to the qBittorrent source download root, then rerun summary-check."],
    }
    assert payload["readiness_summary"]["source_command_recovery"] == payload["source_command_recovery"]
    shell_fields = ptcli_cli._summary_check_readiness_shell_fields(payload["readiness_summary"])
    assert shell_fields["PTCLI_READINESS_SOURCE_COMMAND_RECOVERY_PRESENT"] == "1"
    assert shell_fields["PTCLI_READINESS_SOURCE_COMMAND_RECOVERY_MISSING"] == "source_save_path"
    assert shell_fields["PTCLI_READINESS_SOURCE_COMMAND_RECOVERY_REQUIRED_FLAGS"] == "--save-path"
    assert shell_fields["PTCLI_READINESS_SOURCE_COMMAND_RECOVERY_EXAMPLE_FLAG"] == "--save-path /downloads"
    assert shell_fields["PTCLI_READINESS_SOURCE_COMMAND_RECOVERY_NEXT_ACTIONS"] == "Add --save-path pointing to the qBittorrent source download root, then rerun summary-check."
    assert payload["automation_reason"] == "Source follow-up command needs additional flags before automatic execution: pipeline source injection requires --save-path before automatic execution."


def test_summary_check_run_next_command_rejects_non_ptcli_command(tmp_path, monkeypatch, capsys) -> None:
    summary_file = tmp_path / "ptcli-run-summary.json"
    summary_file.write_text(
        json.dumps(
            {
                "schema_version": 1,
                "kind": "ptcli.pipeline.run_summary",
                "ready": False,
                "complete": False,
                "blockers": ["target.uploaded"],
                "resume_commands": [{"stage": "resume-target-upload", "command": "sh -c 'echo unsafe'"}],
                "resume_state": {
                    "artifacts": {
                        "source_hash_consistent": True,
                        "target_hash_consistent": True,
                        "target_duplicate_clean": True,
                        "target_rule_obligations": True,
                        "target_preparation_ready": True,
                    },
                },
            }
        ),
        encoding="utf-8",
    )
    def fail_run(*_args, **_kwargs):
        pytest.fail("unexpected subprocess call")

    monkeypatch.setattr(ptcli_cli.subprocess, "run", fail_run)

    code = main(["summary-check", "--summary-file", str(summary_file), "--run-next-command"])

    captured = capsys.readouterr()
    assert code == 2
    assert captured.out == ""
    assert "Refusing to run unsupported summary next_command" in captured.err


