def test_job_store_resume_blocks_without_next_command(tmp_path) -> None:
    store = ptcli_service.JobStore(tmp_path, run_inline=True)
    parent = store.create("ptcli.test", {}, ["ptcli", "retorrent"], lambda: {"status": "blocked", "blockers": ["missing"]})

    resume = store.resume(parent["job_id"])

    assert resume["kind"] == "ptcli.resume"
    assert resume["status"] == "blocked"
    assert resume["blockers"] == ["No executable resume command is available for this job."]
    assert parent["resume_plan"]["available"] is False
    assert parent["resume_plan"]["allowed"] is False
    assert parent["resume_plan"]["recommended"] is False
    assert parent["resume_plan"]["blocker"] == "No executable resume command is available for this job."
    assert parent["resume_summary"]["available"] is False
    assert parent["resume_summary"]["allowed"] is False
    assert parent["resume_summary"]["recommended"] is False
    assert "No executable resume command is available for this job." in parent["resume_summary"]["blockers"]
    assert parent["job_resume_handoff"]["action"] == "unavailable"
    assert parent["job_resume_handoff"]["ready"] is False
    assert "No executable resume command is available for this job." in parent["job_resume_handoff"]["blockers"]


def test_job_store_resume_runs_allowlisted_command(monkeypatch, tmp_path) -> None:
    store = ptcli_service.JobStore(tmp_path, run_inline=True)
    parent = store.create(
        "ptcli.test",
        {
            "source_reference": {"tracker": "U2", "source_id": "60635", "url": "https://u2.dmhy.org/details.php?id=60635"},
            "target_trackers": ["MTEAM"],
            "policy_coverage": {"ready": True},
            "policy_qbit_defaults": {"applied": {"qbit_download_limit": 20971520}},
        },
        ["ptcli", "retorrent"],
        lambda: {"status": "blocked", "next_command_argv": ["python3", "ptcli.py", "doctor", "--json"]},
    )

    def fake_run_resume_command(argv, *, parent_job_id):
        return {"status": "ok", "parent_job_id": parent_job_id, "command_argv": argv}

    monkeypatch.setattr(ptcli_service, "_run_resume_command", fake_run_resume_command)

    resume = store.resume(parent["job_id"])

    assert resume["status"] == "complete"
    assert resume["result_status"] == "ok"
    assert resume["command_argv"] == ["python3", "ptcli.py", "doctor", "--json"]
    assert resume["request"]["parent_policy_coverage"] == {"ready": True}
    assert resume["request"]["parent_policy_qbit_defaults"] == {"applied": {"qbit_download_limit": 20971520}}
    assert resume["request"]["resume_context"]["parent_job_id"] == parent["job_id"]
    assert resume["request"]["resume_context"]["resume_allowed"] is True
    assert resume["request"]["resume_context"]["inherited_policy"]["policy_coverage"] == {"ready": True}
    assert resume["request"]["resume_context"]["parent_workflow_context"]["gates"]["resume_allowed"] is True
    assert resume["request"]["resume_lineage"]["parent_job_id"] == parent["job_id"]
    assert resume["request"]["resume_lineage"]["parent_kind"] == "ptcli.test"
    assert resume["request"]["resume_lineage"]["parent_source_reference"] == parent["source_reference"]
    assert resume["request"]["resume_lineage"]["parent_target_trackers"] == ["MTEAM"]
    assert resume["request"]["resume_lineage"]["parent_workflow_context"]["source_reference"] == parent["source_reference"]
    assert resume["request"]["resume_lineage"]["next_subcommand"] == "doctor"
    assert resume["resume_lineage"] == resume["request"]["resume_lineage"]
    assert resume["job_lineage"]["parent_job_id"] == parent["job_id"]
    assert resume["job_lineage"]["root_job_id"] == parent["job_id"]
    assert resume["job_lineage"]["depth"] == 1
    assert [item["job_id"] for item in resume["job_lineage"]["chain"]] == [parent["job_id"], resume["job_id"]]
    assert resume["source_reference"] == parent["source_reference"]
    assert resume["workflow_context"]["resume_lineage"] == resume["resume_lineage"]
    assert resume["resume_context"] == resume["request"]["resume_context"]
    assert resume["resume_audit"]["is_resume_job"] is True
    assert resume["resume_audit"]["parent_job_id"] == parent["job_id"]
    assert resume["resume_audit"]["parent_kind"] == "ptcli.test"
    assert resume["resume_audit"]["child_status"] == "complete"
    assert resume["resume_audit"]["next_subcommand"] == "doctor"
    assert resume["resume_audit"]["next_command_argv"] == ["python3", "ptcli.py", "doctor", "--json"]
    assert resume["resume_audit"]["summary_endpoint"] == f"/v1/jobs/{resume['job_id']}/summary"
    assert resume["resume_summary"]["available"] is False
    assert resume["resume_summary"]["allowed"] is False
    assert resume["agent_decision"]["resume_summary"] == resume["resume_summary"]
    assert resume["material_resolution"] is None
    assert resume["agent_decision"]["resume_context"] == resume["resume_context"]
    assert resume["agent_decision"]["resume_lineage"] == resume["resume_lineage"]
    assert resume["agent_decision"]["resume_requirements"]["subcommand"] is None
    assert parent["resume_plan"]["available"] is True
    assert parent["resume_plan"]["allowed"] is True
    assert parent["resume_plan"]["recommended"] is True
    assert parent["resume_plan"]["subcommand"] == "doctor"
    assert parent["resume_plan"]["endpoint"] == f"/v1/jobs/{parent['job_id']}/resume"

    parent_after_resume = store.get(parent["job_id"])
    parent_summary = store.summary(parent["job_id"])
    child_summary = store.summary(resume["job_id"])
    listed = store.list({"kind": "ptcli.resume"})

    assert parent_after_resume["job_lineage"]["child_count"] == 1
    assert parent_after_resume["job_lineage"]["latest_child"]["job_id"] == resume["job_id"]
    assert parent_after_resume["job_lineage"]["children"][0]["status"] == "complete"
    assert parent_summary["job_lineage"] == parent_after_resume["job_lineage"]
    assert child_summary["job_lineage"]["parent_job_id"] == parent["job_id"]
    assert child_summary["job_lineage"]["root_job_id"] == parent["job_id"]
    assert listed["jobs"][0]["job_lineage"]["parent_job_id"] == parent["job_id"]
    assert listed["jobs"][0]["job_lineage"]["chain"][0]["job_id"] == parent["job_id"]


def test_job_store_resume_applies_allowlisted_overrides(monkeypatch, tmp_path) -> None:
    store = ptcli_service.JobStore(tmp_path, run_inline=True)
    parent = store.create(
        "ptcli.test",
        {"source_reference": {"tracker": "U2", "source_id": "60635"}, "target_trackers": ["MTEAM"]},
        ["ptcli", "retorrent"],
        lambda: {
            "status": "blocked",
            "next_command_argv": [
                "python3",
                "ptcli.py",
                "pipeline",
                "--from",
                "U2",
                "--source-id",
                "60635",
                "--to",
                "MTEAM",
                "--save-path",
                "/old",
                "--screenshot-file",
                "/old/screen.png",
                "--json",
            ],
            "material_diagnostics": {
                "present": True,
                "ready_for_mteam_upload": False,
                "critical_ready": False,
                "critical_missing": ["metadata.tmdb", "description.content"],
                "metadata_fields": {
                    "tmdb_id": {"ready": False},
                    "ptgen_description": {"ready": False},
                },
                "description": {
                    "ready": False,
                    "has_ptgen_description": False,
                    "has_mediainfo_or_bdinfo": True,
                    "has_screenshot_bbcode": False,
                    "external_id_readiness": {"tmdb": False},
                    "external_id_missing": ["tmdb"],
                },
                "upload_material_blockers": ["materials.assets.image_host_uploads"],
            },
            "target_preflight_diagnostics": {"ready": False, "payload_ready": False, "description_ready": False},
        },
    )

    def fake_run_resume_command(argv, *, parent_job_id):
        return {"status": "ok", "parent_job_id": parent_job_id, "command_argv": argv}

    monkeypatch.setattr(ptcli_service, "_run_resume_command", fake_run_resume_command)

    resume = store.resume(
        parent["job_id"],
        {
            "accept_rules": True,
            "confirm_upload": True,
            "save_path": "/downloads",
            "metadata_file": "/tmp/metadata.json",
            "ptgen_description_file": "/tmp/ptgen.txt",
            "uploaded_qbit_upload_limit": "2MiB/s",
            "screenshot_files": ["/tmp/1.png", "/tmp/2.png"],
            "image_host_file": "/tmp/image-host.json",
            "dangerous_shell": "nope",
        },
    )

    argv = resume["command_argv"]
    assert resume["status"] == "complete"
    assert "--accept-rules" in argv
    assert "--confirm-upload" in argv
    assert argv[argv.index("--save-path") + 1] == "/downloads"
    assert argv[argv.index("--metadata-file") + 1] == "/tmp/metadata.json"
    assert argv[argv.index("--ptgen-description-file") + 1] == "/tmp/ptgen.txt"
    assert argv[argv.index("--uploaded-qbit-upload-limit") + 1] == "2MiB/s"
    assert argv[argv.index("--image-host-file") + 1] == "/tmp/image-host.json"
    screenshot_indexes = [index for index, item in enumerate(argv) if item == "--screenshot-file"]
    assert [argv[index + 1] for index in screenshot_indexes] == ["/tmp/1.png", "/tmp/2.png"]
    assert "/old" not in argv
    assert "/old/screen.png" not in argv
    assert resume["request"]["original_next_command_argv"] == parent["next_command_argv"]
    assert resume["request"]["next_command_argv"] == argv
    assert resume["request"]["applied_overrides"]
    assert {"key": "dangerous_shell", "reason": "override is not allowlisted for resume commands"} in resume["request"]["ignored_overrides"]
    material_resolution = resume["resume_context"]["material_resolution"]
    assert material_resolution["kind"] == "ptcli.resume_material_resolution"
    assert material_resolution["ready_before_resume"] is False
    assert material_resolution["covered_recommended_inputs"] == [
        "path_or_save_path",
        "metadata_file",
        "ptgen_description_file",
        "screenshot_files",
        "image_host_file",
    ]
    assert material_resolution["unresolved_recommended_inputs"] == []
    assert "metadata_file" in material_resolution["applied_override_keys"]
    assert "dangerous_shell" in material_resolution["ignored_override_keys"]
    assert resume["request"]["material_resolution"] == material_resolution
    assert resume["request"]["parent_materials_handoff"]["blockers"]
    assert resume["material_resolution"] == material_resolution
    assert resume["workflow_context"]["material_resolution"] == material_resolution
    assert resume["agent_decision"]["material_resolution"] == material_resolution
    assert resume["resume_context"]["applied_overrides"] == resume["request"]["applied_overrides"]
    assert resume["resume_context"]["ignored_overrides"] == resume["request"]["ignored_overrides"]


def test_resume_recommended_inputs_expose_material_recovery_paths() -> None:
    inputs = ptcli_service._resume_recommended_inputs(
        {},
        {
            "ready": False,
            "imdb_ready": False,
            "tmdb_ready": False,
            "douban_ready": False,
            "ptgen_description_ready": False,
            "missing": ["metadata.imdb", "metadata.tmdb", "metadata.douban"],
        },
        {
            "critical_missing": [
                "metadata.imdb",
                "metadata.tmdb",
                "metadata.douban",
                "description.content",
                "materials.description.screenshot_coverage",
            ],
            "upload_material_blockers": ["materials.assets.image_host_uploads"],
            "mediainfo_or_bdinfo_ready": False,
            "screenshots_ready": False,
        },
        {
            "payload_ready": False,
            "description_ready": False,
            "description_missing": ["materials.description.ptgen_description"],
            "blockers": ["materials.description.screenshot_coverage"],
        },
    )

    by_key = {item["key"]: item for item in inputs}
    assert list(by_key) == [
        "path_or_save_path",
        "metadata_file",
        "ptgen_description_file",
        "mediainfo_or_bdinfo",
        "screenshot_files",
        "image_host_file",
    ]
    assert {"path", "content_path", "save_path"}.issubset(by_key["path_or_save_path"]["accepted_keys"])
    assert {"metadata_file", "imdb_id", "tmdb_id", "tmdb_type", "douban_id", "douban_url", "enrich_metadata", "fetch_ptgen"}.issubset(by_key["metadata_file"]["accepted_keys"])
    assert {"ptgen_description_file", "metadata_file", "fetch_ptgen", "enrich_metadata", "douban_id", "douban_url"}.issubset(by_key["ptgen_description_file"]["accepted_keys"])
    assert {"mediainfo_file", "bdinfo_file", "generate_mediainfo", "generate_bdinfo"}.issubset(by_key["mediainfo_or_bdinfo"]["accepted_keys"])
    assert {"screenshot_files", "screenshot_file", "generate_screenshots", "screenshot_count"}.issubset(by_key["screenshot_files"]["accepted_keys"])
    assert {"image_host_file", "upload_screenshots", "image_host"}.issubset(by_key["image_host_file"]["accepted_keys"])
    assert by_key["image_host_file"]["stage"] == "materials-image-host"
    assert by_key["image_host_file"]["resume_tool"] == "resume_job"


def test_job_store_lists_recent_jobs_with_filters(tmp_path) -> None:
    store = ptcli_service.JobStore(tmp_path, run_inline=True)
    complete = store.create("ptcli.complete", {"source_reference": {"tracker": "CHD", "source_id": "1"}}, ["ptcli", "sites"], lambda: {"status": "ok"})
    blocked = store.create(
        "ptcli.blocked",
        {"source_reference": {"tracker": "U2", "source_id": "60635"}, "target_trackers": ["MTEAM"]},
        ["ptcli", "retorrent"],
        lambda: {"status": "blocked", "blockers": ["materials missing"], "next_command_argv": ["python3", "ptcli.py", "doctor", "--json"]},
    )

    payload = store.list({"status": "blocked", "limit": "10"})

    assert payload["status"] == "ok"
    assert payload["count"] == 1
    assert payload["total"] == 1
    assert payload["filters"] == {"status": "blocked", "kind": None}
    assert payload["status_counts"]["complete"] == 1
    assert payload["status_counts"]["blocked"] == 1
    assert payload["jobs"][0]["job_id"] == blocked["job_id"]
    assert payload["jobs"][0]["status_endpoint"] == f"/v1/jobs/{blocked['job_id']}"
    assert payload["jobs"][0]["summary_endpoint"] == f"/v1/jobs/{blocked['job_id']}/summary"
    assert payload["jobs"][0]["resume_endpoint"] == f"/v1/jobs/{blocked['job_id']}/resume"
    assert payload["jobs"][0]["source_reference"] == {"tracker": "U2", "source_id": "60635"}
    assert payload["jobs"][0]["target_trackers"] == ["MTEAM"]
    assert payload["jobs"][0]["resume_plan"]["recommended"] is True
    assert payload["jobs"][0]["resume_requirements"]["can_call_resume"] is True
    assert payload["jobs"][0]["resume_requirements"]["subcommand"] == "doctor"
    assert payload["jobs"][0]["resume_audit"]["resume_recommended"] is True
    assert payload["jobs"][0]["resume_audit"]["next_step"]["tool"] == "resume_job"
    assert payload["jobs"][0]["resume_audit"]["dry_run_request"] == {"job_id": blocked["job_id"], "dry_run": True}
    assert payload["jobs"][0]["job_handoff"]["action"] == "resume"
    assert payload["jobs"][0]["job_handoff"]["recommended_tool"] == "resume_job"
    assert payload["jobs"][0]["job_handoff"]["recommended_request"] == {"job_id": blocked["job_id"], "dry_run": True}
    assert payload["jobs"][0]["job_control_summary"]["action"] == "resume_preview"
    assert payload["jobs"][0]["job_control_summary"]["recommended_tool"] == "resume_job"
    assert payload["jobs"][0]["job_control_summary"]["dry_run_request"] == {"job_id": blocked["job_id"], "dry_run": True}
    assert "Resume recommended blocked jobs" in payload["next_actions"][-1]

    limited = store.list({"limit": "1"})
    assert limited["count"] == 1
    assert limited["total"] == 2
    assert limited["jobs"][0]["job_id"] in {complete["job_id"], blocked["job_id"]}
    assert any("Increase limit" in action for action in limited["next_actions"])


