class _NonClosingBytesIO(io.BytesIO):
    def close(self) -> None:
        self.flush()


class _FakeSocket:
    def __init__(self, request_bytes: bytes) -> None:
        self.input = io.BytesIO(request_bytes)
        self.output = _NonClosingBytesIO()

    def makefile(self, mode: str, *_args, **_kwargs):
        return self.input if "r" in mode else self.output

    def sendall(self, data: bytes) -> None:
        self.output.write(data)


class _FakeServer:
    server_address = ("127.0.0.1", 8080)


def _service_json_request(handler_class, method: str, path: str, *, payload: dict | None = None, api_token: str | None = None) -> tuple[int, dict]:
    body = json.dumps(payload).encode("utf-8") if payload is not None else None
    headers = {
        "Host": "127.0.0.1:8080",
        "Content-Type": "application/json",
    }
    if api_token:
        headers["Authorization"] = f"Bearer {api_token}"
    if body is not None:
        headers["Content-Length"] = str(len(body))
    raw_headers = "".join(f"{key}: {value}\r\n" for key, value in headers.items()).encode("utf-8")
    raw_request = f"{method} {path} HTTP/1.1\r\n".encode() + raw_headers + b"\r\n" + (body or b"")
    fake_socket = _FakeSocket(raw_request)
    handler_class(fake_socket, ("127.0.0.1", 12345), _FakeServer())
    raw_response = fake_socket.output.getvalue()
    status_line, response_body = raw_response.split(b"\r\n", 1)[0], raw_response.split(b"\r\n\r\n", 1)[1]
    return int(status_line.decode("utf-8").split()[1]), json.loads(response_body.decode("utf-8"))


def test_http_source_url_retorrent_job_endpoint_requires_auth_and_returns_ai_context(monkeypatch, tmp_path) -> None:
    captured_request = {}

    async def fake_retorrent(request):
        captured_request.update(request)
        return {
            "kind": "ptcli.service.retorrent",
            "status": "blocked",
            "ok": False,
            "blockers": ["rule gate requires explicit confirmations."],
            "next_actions": ["Review source and target rules, then resubmit with confirmations."],
            "duplicate_check": {"searched": True, "status": "not_found", "exists": False, "count": 0, "dupes": []},
        }

    monkeypatch.setattr(ptcli_service, "retorrent", fake_retorrent)
    store = ptcli_service.JobStore(tmp_path / "jobs", run_inline=True)
    handler_class = ptcli_service._handler_class("secret", store)
    request = {
        "source_url": "https://u2.dmhy.org/details.php?id=60635&hit=1",
        "target": "MTEAM",
        "save_path": "/downloads",
        "metadata_file": "/tmp/materials/metadata.json",
        "mediainfo_file": "/tmp/materials/MI_FULL_00.txt",
        "screenshot_files": ["/tmp/materials/screen-01.png"],
        "image_host_file": "/tmp/materials/image-host-uploads.json",
        "fetch_ptgen": True,
        "generate_mediainfo": True,
        "generate_screenshots": True,
        "upload_screenshots": True,
    }

    unauthorized_status, unauthorized_body = _service_json_request(handler_class, "POST", "/v1/jobs/retorrent/from-url", payload=request)
    assert unauthorized_status == 401
    assert unauthorized_body["message"] == "Unauthorized."
    assert captured_request == {}

    status, payload = _service_json_request(handler_class, "POST", "/v1/jobs/retorrent/from-url", payload=request, api_token="secret")
    assert status == 200
    assert payload["kind"] == "ptcli.source_url_retorrent"
    assert payload["status"] == "blocked"
    assert payload["request"]["mode"] == "source_url_retorrent"
    assert payload["source_reference"]["tracker"] == "U2"
    assert payload["source_reference"]["source_id"] == "60635"
    assert payload["agent_decision"]["source_reference"] == payload["source_reference"]
    assert payload["workflow_context"]["gates"]["source_resolved"] is True
    assert payload["workflow_context"]["required_confirmations_missing"] == ["accept_rules=true", "confirm_upload=true"]
    assert payload["manual_retorrent_handoff"]["action"] == "collect_confirmations"
    assert payload["manual_retorrent_handoff"]["status_endpoint"] == f"/v1/jobs/{payload['job_id']}"
    assert payload["manual_retorrent_handoff"]["summary_endpoint"] == f"/v1/jobs/{payload['job_id']}/summary"
    assert captured_request["source"] == request["source_url"]
    assert captured_request["source_url"] == request["source_url"]
    assert captured_request["metadata_file"] == request["metadata_file"]
    assert captured_request["screenshot_files"] == request["screenshot_files"]
    assert captured_request["upload_screenshots"] is True
    assert payload["request"]["material_options"] == {
        "metadata_file": "/tmp/materials/metadata.json",
        "mediainfo_file": "/tmp/materials/MI_FULL_00.txt",
        "image_host_file": "/tmp/materials/image-host-uploads.json",
        "screenshot_files": ["/tmp/materials/screen-01.png"],
        "fetch_ptgen": True,
        "generate_mediainfo": True,
        "generate_screenshots": True,
        "upload_screenshots": True,
    }

    status, job_status = _service_json_request(handler_class, "GET", f"/v1/jobs/{payload['job_id']}", api_token="secret")
    assert status == 200
    assert job_status["job_id"] == payload["job_id"]
    assert job_status["source_reference"] == payload["source_reference"]
    assert job_status["workflow_context"] == payload["workflow_context"]
    assert job_status["manual_retorrent_handoff"] == payload["manual_retorrent_handoff"]
    assert job_status["command_argv"][:7] == ["ptcli", "retorrent", "--from", "U2", "--source-id", "60635", "--to"]
    assert job_status["request"]["material_options"] == payload["request"]["material_options"]
    assert "--generate-screenshots" in job_status["command_argv"]
    assert "--upload-screenshots" in job_status["command_argv"]

    unauthorized_status, unauthorized_body = _service_json_request(handler_class, "GET", "/v1/jobs?status=blocked&limit=10")
    assert unauthorized_status == 401
    assert unauthorized_body["message"] == "Unauthorized."

    status, job_list = _service_json_request(handler_class, "GET", "/v1/jobs?status=blocked&limit=10", api_token="secret")
    assert status == 200
    assert job_list["status"] == "ok"
    assert job_list["count"] == 1
    assert job_list["filters"] == {"status": "blocked", "kind": None}
    assert job_list["jobs"][0]["job_id"] == payload["job_id"]
    assert job_list["jobs"][0]["source_reference"] == payload["source_reference"]
    assert job_list["jobs"][0]["manual_retorrent_handoff"]["action"] == "collect_confirmations"
    assert job_list["jobs"][0]["status_endpoint"] == f"/v1/jobs/{payload['job_id']}"
    assert job_list["jobs"][0]["summary_endpoint"] == f"/v1/jobs/{payload['job_id']}/summary"
    assert job_list["jobs"][0]["resume_endpoint"] == f"/v1/jobs/{payload['job_id']}/resume"


def test_http_cancel_job_endpoint_requires_auth_and_only_cancels_queued(tmp_path) -> None:
    queued_id = "e" * 32
    running_id = "f" * 32
    base_job = {
        "schema_version": 1,
        "kind": "ptcli.retorrent",
        "ok": False,
        "request": {},
        "command_argv": ["ptcli", "retorrent", "--json"],
        "created_at": 100,
        "updated_at": 105,
        "started_at": None,
        "completed_at": None,
        "blockers": [],
        "next_actions": [],
        "summary_file": None,
        "resume_state": None,
        "agent_summary": None,
        "agent_decision": None,
        "duplicate_check": None,
        "result": None,
    }
    (tmp_path / f"{queued_id}.json").write_text(json.dumps({**base_job, "job_id": queued_id, "status": "queued"}), encoding="utf-8")
    (tmp_path / f"{running_id}.json").write_text(json.dumps({**base_job, "job_id": running_id, "status": "running", "started_at": 105}), encoding="utf-8")
    store = ptcli_service.JobStore(tmp_path, run_inline=True, recover_interrupted=False)
    handler_class = ptcli_service._handler_class("secret", store)

    unauthorized_status, unauthorized_body = _service_json_request(handler_class, "POST", f"/v1/jobs/{queued_id}/cancel", payload={"reason": "mistake"})
    assert unauthorized_status == 401
    assert unauthorized_body["message"] == "Unauthorized."

    status, payload = _service_json_request(handler_class, "POST", f"/v1/jobs/{queued_id}/cancel", payload={"reason": "mistake"}, api_token="secret")
    assert status == 200
    assert payload["status"] == "cancelled"
    assert payload["cancellation"]["reason"] == "mistake"
    assert payload["agent_decision"]["stop_reason"] == "job_cancelled"

    status, conflict = _service_json_request(handler_class, "POST", f"/v1/jobs/{running_id}/cancel", payload={"reason": "mistake"}, api_token="secret")
    assert status == 409
    assert "Only queued jobs can be cancelled" in conflict["message"]


def test_http_resume_job_endpoint_accepts_allowlisted_overrides(monkeypatch, tmp_path) -> None:
    calls = []

    def fake_run_resume_command(argv, *, parent_job_id):
        calls.append({"argv": argv, "parent_job_id": parent_job_id})
        return {"status": "ok", "parent_job_id": parent_job_id, "command_argv": argv}

    monkeypatch.setattr(ptcli_service, "_run_resume_command", fake_run_resume_command)
    store = ptcli_service.JobStore(tmp_path, run_inline=True)
    parent = store.create(
        "ptcli.test",
        {},
        ["ptcli", "retorrent"],
        lambda: {"status": "blocked", "next_command_argv": ["python3", "ptcli.py", "doctor", "--json"]},
    )
    handler_class = ptcli_service._handler_class("secret", store)

    preview_status, preview = _service_json_request(
        handler_class,
        "POST",
        f"/v1/jobs/{parent['job_id']}/resume",
        payload={"dry_run": True, "confirm_upload": True, "uploaded_save_path": "/downloads/Example"},
        api_token="secret",
    )

    assert preview_status == 202
    assert preview["kind"] == "ptcli.resume_preview"
    assert preview["status"] == "ok"
    assert preview["dry_run"] is True
    assert preview["mutates_state"] is False
    assert preview["parent_job_id"] == parent["job_id"]
    assert "--confirm-upload" in preview["command_argv"]
    assert preview["command_argv"][preview["command_argv"].index("--uploaded-save-path") + 1] == "/downloads/Example"
    assert preview["resume_overrides"] == {"confirm_upload": True, "uploaded_save_path": "/downloads/Example"}
    assert preview["ignored_overrides"] == []
    assert preview["resume_audit"]["kind"] == "ptcli.resume_preview_audit"
    assert preview["resume_audit"]["dry_run"] is True
    assert preview["resume_audit"]["parent_job_id"] == parent["job_id"]
    assert preview["resume_audit"]["applied_override_keys"] == ["confirm_upload", "uploaded_save_path"]
    assert preview["resume_audit"]["next_command_argv"] == preview["command_argv"]
    assert preview["agent_decision"]["decision"] == "resume_preview"
    assert calls == []

    status, payload = _service_json_request(
        handler_class,
        "POST",
        f"/v1/jobs/{parent['job_id']}/resume",
        payload={"confirm_upload": True, "uploaded_save_path": "/downloads/Example"},
        api_token="secret",
    )

    assert status == 202
    assert payload["kind"] == "ptcli.resume"
    assert payload["status"] == "complete"
    assert "--confirm-upload" in payload["command_argv"]
    assert payload["command_argv"][payload["command_argv"].index("--uploaded-save-path") + 1] == "/downloads/Example"
    assert payload["request"]["resume_overrides"] == {"confirm_upload": True, "uploaded_save_path": "/downloads/Example"}
    assert payload["resume_context"]["parent_job_id"] == parent["job_id"]
    assert payload["resume_audit"]["parent_job_id"] == parent["job_id"]
    assert payload["resume_audit"]["applied_override_keys"] == ["confirm_upload", "uploaded_save_path"]
    assert payload["resume_audit"]["ignored_override_keys"] == []
    assert payload["resume_audit"]["execute_request"]["job_id"] == payload["job_id"]
    assert calls == [{"argv": payload["command_argv"], "parent_job_id": parent["job_id"]}]


def test_manual_retorrent_job_requests_policy_config_when_coverage_missing(monkeypatch, tmp_path) -> None:
    config = {
        "PTCLI": {
            "SITE_POLICIES": {
                "U2": {"allow_auto_download": True, "allow_retorrent": True},
                "MTEAM": {"allow_auto_upload": True, "allow_retorrent": True},
            }
        }
    }

    async def fake_retorrent(_request):
        return {
            "kind": "ptcli.service.retorrent",
            "status": "blocked",
            "ok": False,
            "blockers": ["target duplicate check or live upload gate blocked execution."],
            "next_actions": ["Review blockers and resume with explicit confirmations when safe."],
            "duplicate_check": {"searched": True, "status": "not_found", "exists": False, "count": 0, "dupes": []},
        }

    monkeypatch.setattr(ptcli_service, "retorrent", fake_retorrent)
    monkeypatch.setattr(ptcli_service, "load_config", lambda _path=None: config)
    store = ptcli_service.JobStore(tmp_path, run_inline=True)

    job = ptcli_service.create_manual_retorrent_job(
        store,
        {
            "source": "https://u2.dmhy.org/details.php?id=60635",
            "target": "MTEAM",
            "accept_rules": True,
            "confirm_upload": True,
        },
    )

    assert job["status"] == "blocked"
    assert job["policy_coverage"]["ready"] is False
    assert job["policy_coverage"]["missing_policy_fields"] == {
        "U2": ["rule_review_fingerprint", "download_rate_limit", "min_seed_time_hours"],
        "MTEAM": ["rule_review_fingerprint", "upload_rate_limit", "min_ratio"],
    }
    assert job["agent_decision"]["decision"] == "configure_policy"
    assert job["agent_decision"]["stop_reason"] == "policy_coverage_incomplete"
    assert job["agent_decision"]["can_attempt_live"] is False
    assert "rule_review_fingerprint" in job["agent_decision"]["policy_coverage"]["missing_policy_fields"]["U2"]


def test_agent_decision_stops_manual_retorrent_when_duplicate_exists(monkeypatch, tmp_path) -> None:
    async def fake_retorrent(_request):
        return {
            "kind": "ptcli.service.retorrent",
            "status": "blocked",
            "ok": False,
            "blockers": ["target-duplicate: target tracker already has possible existing torrents."],
            "next_actions": ["Do not upload this torrent to the target tracker."],
            "duplicate_check": {"searched": True, "status": "exists", "exists": True, "count": 1, "dupes": [{"name": "Existing.Release"}]},
        }

    monkeypatch.setattr(ptcli_service, "retorrent", fake_retorrent)
    store = ptcli_service.JobStore(tmp_path, run_inline=True)

    job = ptcli_service.create_manual_retorrent_job(
        store,
        {
            "source": "https://u2.dmhy.org/details.php?id=60635",
            "target": "MTEAM",
            "accept_rules": True,
            "confirm_upload": True,
        },
    )
    summary = store.summary(job["job_id"])

    assert job["status"] == "blocked"
    assert job["agent_decision"]["decision"] == "stop"
    assert job["agent_decision"]["stop_reason"] == "target_duplicate_exists"
    assert job["agent_decision"]["can_attempt_live"] is False
    assert summary["agent_decision"]["duplicate_check"]["count"] == 1


