def test_daily_schedule_cli_runs_configured_schedules(monkeypatch, tmp_path, capsys) -> None:
    digest = {
        "kind": "ptcli.daily_candidates_digest",
        "recommendation": "submit_top_candidate_when_confirmed",
        "ready_count": 1,
        "top_candidate": {"source_tracker": "CHD", "source_id": "12345"},
        "top_submit_request": {"source": "https://chdbits.co/details.php?id=12345", "target": "MTEAM"},
        "top_submit_job_endpoint": "/v1/jobs/retorrent/from-url",
        "top_submit_tool": "source_url_retorrent_job",
        "approval_queue": {
            "kind": "ptcli.daily_candidate_approval_queue",
            "ready": True,
            "safe_count": 1,
            "items": [
                {
                    "rank": 1,
                    "source_tracker": "CHD",
                    "source_id": "12345",
                    "source_url": "https://chdbits.co/details.php?id=12345",
                    "title": "Example",
                    "risk_level": "low",
                    "policy_risk_level": "low",
                    "duplicate_clear": True,
                    "request": {"source": "https://chdbits.co/details.php?id=12345", "target": "MTEAM"},
                    "policy_risk_summary": {"risk_level": "low"},
                }
            ],
            "top_safe_candidates": [
                {
                    "rank": 1,
                    "source_tracker": "CHD",
                    "source_id": "12345",
                    "source_url": "https://chdbits.co/details.php?id=12345",
                    "title": "Example",
                    "risk_level": "low",
                    "policy_risk_level": "low",
                    "duplicate_clear": True,
                    "request": {"source": "https://chdbits.co/details.php?id=12345", "target": "MTEAM"},
                    "policy_risk_summary": {"risk_level": "low"},
                }
            ],
        },
        "top_safe_candidates": [
            {
                "rank": 1,
                "source_tracker": "CHD",
                "source_id": "12345",
                "source_url": "https://chdbits.co/details.php?id=12345",
                "title": "Example",
                "risk_level": "low",
                "policy_risk_level": "low",
                "duplicate_clear": True,
                "request": {"source": "https://chdbits.co/details.php?id=12345", "target": "MTEAM"},
                "policy_risk_summary": {"risk_level": "low"},
            }
        ],
        "push_items": [{"rank": 1, "source_id": "12345", "title": "Example"}],
    }

    async def fake_daily_candidates(_request):
        return {
            "kind": "ptcli.service.daily_candidates",
            "status": "ok",
            "ok": True,
            "digest": digest,
            "candidates": [{"status": "ready"}],
            "blockers": [],
            "next_actions": [],
        }

    webhook_calls = []

    class FakeWebhookResponse:
        status_code = 204

    def fake_post(url, *, json, timeout):
        webhook_calls.append({"url": url, "json": json, "timeout": timeout})
        return FakeWebhookResponse()

    monkeypatch.setattr(ptcli_service, "daily_candidates", fake_daily_candidates)
    monkeypatch.setattr(ptcli_cli.requests, "post", fake_post)
    schedules_file = tmp_path / "schedules.json"
    schedules_file.write_text(json.dumps([{"name": "chd-to-mteam", "source_tracker": "CHD", "target": "MTEAM", "accept_rules": True}]), encoding="utf-8")

    code = main(
        [
            "daily-schedule",
            "--job-dir",
            str(tmp_path / "jobs"),
            "--schedules-file",
            str(schedules_file),
            "--write-summary",
            "--summary-output-dir",
            str(tmp_path / "summary"),
            "--write-notification",
            "--notification-webhook-url",
            "https://hooks.example/ptcli",
            "--notification-webhook-timeout",
            "3",
            "--json",
        ]
    )
    payload = json.loads(capsys.readouterr().out)

    assert code == 0
    assert payload["kind"] == "ptcli.cli.daily_schedule"
    assert payload["execution"]["mode"] == "inline"
    assert payload["execution"]["source"] == "schedules_file"
    assert payload["job_count"] == 1
    assert payload["schedule_digest"]["push_items"][0]["schedule_name"] == "chd-to-mteam"
    assert payload["schedule_digest"]["top_submit_requests"][0]["request"]["source"] == "https://chdbits.co/details.php?id=12345"
    assert payload["schedule_digest"]["submission_handoff"]["items"][0]["selector"] == {"rank": 1, "source_id": "12345"}
    assert payload["agent_decision"]["decision"] == "review_candidates"
    assert Path(payload["job_dir"]).is_dir()
    summary_path = Path(payload["summary_file"])
    assert summary_path == tmp_path / "summary" / "ptcli-daily-schedule-summary.json"
    summary = json.loads(summary_path.read_text(encoding="utf-8"))
    assert summary["kind"] == "ptcli.daily_schedule.summary"
    assert summary["schedule_digest"]["top_submit_requests"][0]["request"]["source"] == "https://chdbits.co/details.php?id=12345"
    assert summary["schedule_digest"]["submission_handoff"]["items"][0]["submit_tool"] == "submit_daily_candidate_job"
    assert summary["notification_payload"]["top_item"]["source_id"] == "12345"
    assert summary["notification_payload"]["ready"] is True
    assert summary["notification_files"] == payload["notification_files"]
    assert summary["notification_webhook"] == payload["notification_webhook"]
    assert summary["delivery_handoff"] == payload["delivery_handoff"]
    assert summary["delivery_result"] == payload["delivery_result"]
    assert summary["delivery_audit"] == payload["delivery_audit"]
    assert payload["delivery_result"]["kind"] == "ptcli.daily_schedule.delivery_result"
    assert payload["delivery_result"]["status"] == "delivered"
    assert payload["delivery_result"]["ok"] is True
    assert payload["delivery_result"]["publish_ready"] is True
    assert payload["delivery_result"]["file_delivery"]["ok"] is True
    assert payload["delivery_result"]["webhook_delivery"]["ok"] is True
    assert payload["delivery_result"]["agent_handoff"]["execution_summary"] == "delivery_handoff.execution_summary"
    assert payload["delivery_audit"]["kind"] == "ptcli.daily_schedule.delivery_audit"
    assert payload["delivery_audit"]["ready"] is True
    assert payload["delivery_audit"]["mutates_state"] is False
    assert payload["delivery_audit"]["uploads"] is False
    assert payload["delivery_audit"]["contacts_trackers"] is False
    assert payload["delivery_audit"]["channels"]["file"]["ok"] is True
    assert payload["delivery_audit"]["channels"]["webhook"]["ok"] is True
    assert payload["delivery_audit"]["payload_fingerprint"]
    assert payload["delivery_audit"]["retry"]["safe"] is True
    assert payload["delivery_audit"]["retry"]["requires_upload_confirmation"] is False
    assert "--notification-webhook-url" in payload["delivery_audit"]["retry"]["argv"]
    assert payload["notification_webhook"]["ok"] is True
    assert payload["notification_webhook"]["status_code"] == 204
    assert webhook_calls[0]["url"] == "https://hooks.example/ptcli"
    assert webhook_calls[0]["timeout"] == 3
    assert webhook_calls[0]["json"]["notification_payload"]["top_item"]["source_id"] == "12345"
    assert summary["summary_file"] == str(summary_path)
    notification_json = Path(payload["notification_files"]["json"])
    notification_text = Path(payload["notification_files"]["text"])
    assert notification_json == tmp_path / "summary" / "ptcli-daily-candidates-notification.json"
    assert notification_text == tmp_path / "summary" / "ptcli-daily-candidates-notification.txt"
    assert json.loads(notification_json.read_text(encoding="utf-8"))["notification_payload"]["top_item"]["source_id"] == "12345"
    assert "Daily PT candidate schedule" in notification_text.read_text(encoding="utf-8")

    check_code = main(["summary-check", "--summary-file", str(summary_path), "--json"])
    check_payload = json.loads(capsys.readouterr().out)

    assert check_code == 0
    assert check_payload["kind"] == "ptcli.daily_schedule.summary"
    assert check_payload["ready_for_push"] is True
    assert check_payload["can_submit_any"] is True
    assert check_payload["daily_candidate_targets"]["target_count"] == 10
    assert check_payload["daily_candidate_targets"]["selected_count"] == 1
    assert check_payload["daily_candidate_targets"]["ready_count"] == 1
    assert check_payload["daily_candidate_targets"]["safe_count"] == 1
    assert check_payload["daily_candidate_targets"]["shortfall_count"] == 9
    assert check_payload["daily_candidate_targets"]["target_met"] is False
    assert check_payload["target_count"] == 10
    assert check_payload["shortfall_count"] == 9
    assert check_payload["readiness_summary"]["daily_candidate_targets"] == check_payload["daily_candidate_targets"]
    assert check_payload["readiness_summary"]["daily_candidate_safe_count"] == 1
