def test_daily_schedule_webhook_error_is_reported(monkeypatch, tmp_path, capsys) -> None:
    async def fake_daily_candidates(_request):
        return {
            "kind": "ptcli.service.daily_candidates",
            "status": "ok",
            "ok": True,
            "digest": {
                "kind": "ptcli.daily_candidates_digest",
                "ready_count": 1,
                "top_candidate": {"source_tracker": "U2", "source_id": "60635"},
                "push_items": [{"rank": 1, "source_id": "60635"}],
            },
            "candidates": [{"status": "ready"}],
            "blockers": [],
            "next_actions": [],
        }

    def fake_post(_url, *, json, timeout):
        assert json["notification_payload"]["top_item"]["source_id"] == "60635"
        assert timeout == 10.0
        raise ptcli_cli.requests.RequestException("connection refused")

    monkeypatch.setattr(ptcli_service, "daily_candidates", fake_daily_candidates)
    monkeypatch.setattr(ptcli_cli.requests, "post", fake_post)
    schedules_file = tmp_path / "schedules.json"
    schedules_file.write_text(json.dumps([{"name": "u2-to-mteam", "source_tracker": "U2", "target": "MTEAM", "accept_rules": True}]), encoding="utf-8")

    code = main(
        [
            "daily-schedule",
            "--job-dir",
            str(tmp_path / "jobs"),
            "--schedules-file",
            str(schedules_file),
            "--write-summary",
            "--summary-output-dir",
            str(tmp_path / "summary"),
            "--notification-webhook-url",
            "https://hooks.example/ptcli",
            "--json",
        ]
    )
    payload = json.loads(capsys.readouterr().out)

    assert code == 0
    assert payload["notification_webhook"]["attempted"] is True
    assert payload["notification_webhook"]["ok"] is False
    assert payload["notification_webhook"]["status_code"] is None
    assert "connection refused" in payload["notification_webhook"]["error"]
    assert payload["delivery_result"]["status"] == "blocked"
    assert payload["delivery_result"]["ok"] is False
    assert payload["delivery_result"]["webhook_delivery"]["ok"] is False
    assert "connection refused" in payload["delivery_result"]["blockers"][0]
    assert payload["delivery_audit"]["ready"] is False
    assert payload["delivery_audit"]["channels"]["webhook"]["error"] == "connection refused"
    assert payload["delivery_audit"]["retry"]["safe"] is True
    assert "connection refused" in payload["delivery_audit"]["blockers"][0]
    summary = json.loads(Path(payload["summary_file"]).read_text(encoding="utf-8"))
    assert summary["notification_webhook"] == payload["notification_webhook"]
    assert summary["delivery_result"] == payload["delivery_result"]
    assert summary["delivery_audit"] == payload["delivery_audit"]


def test_daily_scheduler_once_runs_schedule_and_writes_summary(monkeypatch, tmp_path, capsys) -> None:
    digest = {
        "kind": "ptcli.daily_candidates_digest",
        "recommendation": "submit_top_candidate_when_confirmed",
        "ready_count": 1,
        "top_candidate": {"source_tracker": "U2", "source_id": "60635"},
        "top_submit_request": {"source": "https://u2.dmhy.org/details.php?id=60635", "target": "MTEAM"},
        "top_submit_job_endpoint": "/v1/jobs/retorrent/from-url",
        "top_submit_tool": "source_url_retorrent_job",
        "push_items": [{"rank": 1, "source_id": "60635", "title": "Example"}],
    }

    async def fake_daily_candidates(_request):
        return {
            "kind": "ptcli.service.daily_candidates",
            "status": "ok",
            "ok": True,
            "digest": digest,
            "candidates": [{"status": "ready"}],
            "blockers": [],
            "next_actions": [],
        }

    monkeypatch.setattr(ptcli_service, "daily_candidates", fake_daily_candidates)
    schedules_file = tmp_path / "schedules.json"
    schedules_file.write_text(json.dumps([{"name": "u2-to-mteam", "source_tracker": "U2", "target": "MTEAM", "time": "09:30", "timezone": "Asia/Shanghai", "accept_rules": True}]), encoding="utf-8")

    code = main(
        [
            "daily-scheduler",
            "--once",
            "--job-dir",
            str(tmp_path / "jobs"),
            "--schedules-file",
            str(schedules_file),
            "--summary-output-dir",
            str(tmp_path / "summary"),
            "--write-notification",
            "--json",
        ]
    )
    payload = json.loads(capsys.readouterr().out)

    assert code == 0
    assert payload["kind"] == "ptcli.cli.daily_scheduler"
    assert payload["mode"] == "once"
    assert payload["scheduler"]["kind"] == "ptcli.daily_scheduler.plan"
    assert payload["scheduler"]["next_run"]["name"] == "u2-to-mteam"
    assert payload["scheduler"]["next_run"]["job_tool"] == "daily_candidates_job"
    assert payload["last_run"]["kind"] == "ptcli.cli.daily_schedule"
    assert payload["last_run"]["schedule_digest"]["push_items"][0]["source_id"] == "60635"
    assert payload["last_run"]["delivery_result"]["status"] == "delivered"
    assert payload["last_run"]["delivery_result"]["file_delivery"]["ok"] is True
    assert payload["last_run"]["delivery_result"]["webhook_delivery"]["attempted"] is False
    assert Path(payload["last_run"]["notification_files"]["json"]).exists()
    assert Path(payload["last_run"]["notification_files"]["text"]).exists()
    summary_path = Path(payload["summary_file"])
    assert summary_path == tmp_path / "summary" / "ptcli-daily-schedule-summary.json"
    summary_payload = json.loads(summary_path.read_text(encoding="utf-8"))
    assert summary_payload["notification_payload"]["top_item"]["source_id"] == "60635"
    assert summary_payload["notification_files"] == payload["last_run"]["notification_files"]


def test_daily_scheduler_plan_calculates_next_run(tmp_path) -> None:
    schedules_file = tmp_path / "schedules.json"
    schedules_file.write_text(json.dumps([{"name": "u2-to-mteam", "source_tracker": "U2", "target": "MTEAM", "time": "09:30", "timezone": "Asia/Shanghai"}]), encoding="utf-8")
    args = argparse.Namespace(schedules_file=str(schedules_file), schedules_json=None)

    payload = ptcli_cli.daily_scheduler_plan(args, now=datetime.fromisoformat("2026-07-06T09:31:00+08:00"))

    assert payload["status"] == "ok"
    assert payload["enabled_count"] == 1
    assert payload["next_run"]["name"] == "u2-to-mteam"
    assert payload["next_run"]["run_at"] == "2026-07-07T09:30:00+08:00"
    assert payload["next_run"]["seconds_until_run"] == 86340


