async def test_service_qbit_wait_payload_reports_completion(monkeypatch) -> None:
    class FakeQbitReadOnlyService:
        def __init__(self, client_config):
            self.client_config = client_config

        async def wait_for_completion(self, torrent_hash=None, content_path=None, timeout=3600.0, interval=30.0):
            assert torrent_hash == "d" * 40
            assert content_path is None
            assert timeout == 1.5
            assert interval == 0.2
            return {
                "complete": True,
                "query": {"mode": "hash", "torrent_hash": torrent_hash, "content_path": content_path, "timeout": timeout, "interval": interval},
                "matched_count": 1,
                "completion_verification": {
                    "matched_count": 1,
                    "complete_count": 1,
                    "seeding_state_count": 1,
                    "all_matches_complete": True,
                    "any_complete": True,
                    "requested_hash_matched": True,
                    "requested_content_path_matched": None,
                    "observed_hashes": [torrent_hash],
                    "observed_content_paths": ["/downloads/Example.Release"],
                    "observed_save_paths": ["/downloads"],
                    "observed_states": ["uploading"],
                    "observed_progress": [1.0],
                },
                "matches": [
                    {
                        "name": "Example.Release",
                        "hash": torrent_hash,
                        "save_path": "/downloads",
                        "content_path": "/downloads/Example.Release",
                        "size": 1024,
                        "progress": 1.0,
                        "state": "uploading",
                        "category": "MTEAM",
                        "tags": "retorrent",
                        "tracker": "https://tracker.example/announce",
                    }
                ],
            }

    monkeypatch.setattr(ptcli_service, "load_config", lambda _path=None: {"DEFAULT": {"default_torrent_client": "qbit"}, "TORRENT_CLIENTS": {"qbit": {"torrent_client": "qbit", "qbit_url": "http://127.0.0.1", "qbit_port": 8080}}})
    monkeypatch.setattr(ptcli_service, "QbitReadOnlyService", FakeQbitReadOnlyService)

    payload = await ptcli_service.qbit_wait_payload({"hash": "D" * 40, "timeout": 1.5, "interval": 0.2})

    assert payload["status"] == "ok"
    assert payload["ok"] is True
    assert payload["read_only"] is True
    assert payload["client"] == "qbit"
    assert payload["complete"] is True
    assert payload["matched_count"] == 1
    assert payload["agent_summary"]["ready"] is True
    assert payload["agent_summary"]["observed_hashes"] == ["d" * 40]
    assert payload["blockers"] == []
    assert "completion_verification" in payload["next_actions"][0]


async def test_source_url_check_and_submit_creates_job_when_duplicate_clear(monkeypatch) -> None:
    async def fake_retorrent_check(request):
        assert request["source_url"] == "https://u2.dmhy.org/details.php?id=60635"
        assert request["execute"] is False
        duplicate_check = {"searched": True, "exists": False, "count": 0, "dupes": []}
        submit_request = {
            "source_url": request["source_url"],
            "target": "MTEAM",
            "accept_rules": True,
            "confirm_upload": True,
            "save_path": "/downloads",
        }
        return {
            "kind": "ptcli.service.retorrent_check",
            "status": "ok",
            "ok": True,
            "request": submit_request,
            "duplicate_check": duplicate_check,
            "submit_if_clear_handoff": {
                "ready": True,
                "duplicate_clear": True,
                "request": submit_request,
                "blockers": [],
                "next_step": {"tool": "source_url_retorrent_job", "endpoint": "/v1/jobs/retorrent/from-url", "method": "POST", "request": submit_request},
            },
            "blockers": [],
            "next_actions": [],
        }

    def fake_create_source_url_retorrent_job(_job_store, request):
        assert request["source_url"] == "https://u2.dmhy.org/details.php?id=60635"
        assert request["check_submission"]["mode"] == "inline_check_and_submit"
        assert request["check_submission"]["duplicate_check"]["exists"] is False
        return {
            "job_id": "abc123",
            "status": "queued",
            "ok": False,
            "request": request,
            "runtime": {"status_endpoint": "/v1/jobs/abc123"},
        }

    monkeypatch.setattr(ptcli_service, "retorrent_check", fake_retorrent_check)
    monkeypatch.setattr(ptcli_service, "create_source_url_retorrent_job", fake_create_source_url_retorrent_job)

    payload = await ptcli_service.create_source_url_check_and_submit_job(
        object(),
        {
            "source_url": "https://u2.dmhy.org/details.php?id=60635",
            "target": "MTEAM",
            "accept_rules": True,
            "confirm_upload": True,
            "save_path": "/downloads",
        },
    )

    assert payload["status"] == "ok"
    assert payload["ok"] is True
    assert payload["duplicate_check"]["exists"] is False
    assert payload["submit_if_clear_handoff"]["ready"] is True
    assert payload["job_id"] == "abc123"
    assert payload["status_endpoint"] == "/v1/jobs/abc123"
    assert payload["summary_endpoint"] == "/v1/jobs/abc123/summary"
    assert payload["check_and_submit_gate"]["kind"] == "ptcli.check_and_submit_gate"
    assert payload["check_and_submit_gate"]["ready"] is True
    assert payload["check_and_submit_gate"]["action"] == "poll_job"
    assert payload["check_and_submit_gate"]["duplicate_clear"] is True
    assert payload["check_and_submit_gate"]["submit_ready"] is True
    assert payload["check_and_submit_gate"]["accept_rules"] is True
    assert payload["check_and_submit_gate"]["confirm_upload"] is True
    assert payload["check_and_submit_gate"]["recommended_tool"] == "get_job_status"
    assert payload["check_and_submit_gate"]["recommended_request"] == {"job_id": "abc123"}
    sequence = payload["manual_retorrent_sequence"]
    assert sequence["kind"] == "ptcli.manual_retorrent_sequence"
    assert sequence["ready"] is True
    assert sequence["phase"] == "poll_job"
    assert sequence["job_id"] == "abc123"
    assert sequence["duplicate_gate"]["clear"] is True
    assert sequence["recommended_tool"] == "get_job_status"
    assert sequence["recommended_endpoint"] == "/v1/jobs/abc123"
    assert [step["step"] for step in sequence["steps"]] == ["duplicate_gate", "poll_job", "resolve_materials", "prepare_target_package", "target_upload_closure", "final_summary"]
    assert sequence["steps"][4]["tool"] == "target_upload_job"
    assert "uploaded_seeding_ready=true" in sequence["steps"][4]["continue_when"]
    assert sequence["steps"][5]["endpoint"] == "/v1/jobs/abc123/summary"
    assert payload["agent_summary"]["ready"] is True
    assert payload["agent_summary"]["sequence_phase"] == "poll_job"
    assert payload["agent_summary"]["sequence_next_tool"] == "get_job_status"
    assert "Poll get_job_status" in payload["next_actions"][0]


async def test_source_url_check_and_submit_stops_on_duplicate(monkeypatch) -> None:
    async def fake_retorrent_check(request):
        duplicate_check = {"searched": True, "exists": True, "count": 1, "dupes": [{"name": "Existing"}]}
        return {
            "kind": "ptcli.service.retorrent_check",
            "status": "blocked",
            "ok": False,
            "request": request,
            "duplicate_check": duplicate_check,
            "submit_if_clear_handoff": {
                "ready": False,
                "duplicate_clear": False,
                "request": request,
                "blockers": ["duplicate_check.exists"],
                "next_step": {"tool": None, "reason": "submit_if_clear_blocked"},
            },
            "blockers": [],
            "next_actions": [],
        }

    def fail_create_source_url_retorrent_job(_job_store, _request):
        raise AssertionError("live job must not be created when duplicate exists")

    monkeypatch.setattr(ptcli_service, "retorrent_check", fake_retorrent_check)
    monkeypatch.setattr(ptcli_service, "create_source_url_retorrent_job", fail_create_source_url_retorrent_job)

    payload = await ptcli_service.create_source_url_check_and_submit_job(
        object(),
        {
            "source_url": "https://u2.dmhy.org/details.php?id=60635",
            "target": "MTEAM",
            "accept_rules": True,
            "confirm_upload": True,
        },
    )

    assert payload["status"] == "blocked"
    assert payload["ok"] is False
    assert payload["duplicate_check"]["exists"] is True
    assert payload["check_and_submit_gate"]["ready"] is False
    assert payload["check_and_submit_gate"]["action"] == "stop_duplicate"
    assert payload["check_and_submit_gate"]["duplicate_exists"] is True
    assert payload["check_and_submit_gate"]["recommended_tool"] is None
    assert payload["check_and_submit_gate"]["first_blocker"] == "duplicate_check.exists"
    sequence = payload["manual_retorrent_sequence"]
    assert sequence["ready"] is False
    assert sequence["phase"] == "stop_duplicate"
    assert sequence["duplicate_gate"]["exists"] is True
    assert sequence["next_step"]["step"] == "stop_duplicate"
    assert sequence["recommended_tool"] is None
    assert "duplicate exists" in sequence["stop_when"]
    assert payload["job_id"] is None
    assert "duplicate_check.exists" in payload["blockers"]
    assert payload["agent_summary"]["duplicate_exists"] is True
    assert payload["agent_summary"]["sequence_phase"] == "stop_duplicate"
    assert "Do not upload" in payload["next_actions"][0]


def test_site_policies_cli_exposes_policy_gap_summary(monkeypatch, capsys) -> None:
    config = {
        "PTCLI": {
            "SITE_POLICIES": {
                "U2": {
                    "allow_auto_download": True,
                    "allow_retorrent": True,
                    "download_rate_limit": "20MiB/s",
                    "min_seed_time_hours": 72,
                    "rule_review_fingerprint": "u2-review",
                },
                "MTEAM": {
                    "allow_auto_upload": True,
                    "allow_retorrent": True,
                    "upload_rate_limit": "2MiB/s",
                    "min_ratio": 1.0,
                    "rule_review_fingerprint": "mteam-review",
                },
            }
        }
    }
    monkeypatch.setattr(ptcli_service, "load_config", lambda _path=None: config)

    code = main(["site-policies", "--from", "U2", "--to", "MTEAM", "--accept-rules", "--json"])
    payload = json.loads(capsys.readouterr().out)

    assert code == 0
    assert payload["kind"] == "ptcli.site_policies"
    assert payload["ready"] is True
    assert payload["request"]["roles"] == {"U2": ["source"], "MTEAM": ["target"]}
    assert payload["policy_gap_summary"]["ready"] is True
    assert payload["policy_readiness_summary"]["ready"] is True
    assert payload["policy_readiness_summary"]["phase"] == "ready_for_live_preflight"
    assert payload["policy_readiness_summary"]["blocked_trackers"] == []
    assert payload["policy_readiness_summary"]["missing_counts"] == {"rate_limits": 0, "seeding_requirements": 0, "rule_review": 0, "automation": 0}
    assert payload["policy_readiness_summary"]["recommended_tool"] == "readiness_bundle"
    assert payload["policy_repair_gate"]["kind"] == "ptcli.site_policy_repair_gate"
    assert payload["policy_repair_gate"]["ready"] is True
    assert payload["policy_repair_gate"]["action"] == "ready_for_live_preflight"
    assert payload["policy_repair_gate"]["recommended_tool"] == "readiness_bundle"
    assert payload["policy_repair_gate"]["manual_review_required"] is False
    assert payload["policy_repair_gate"]["blockers"] == []
    assert payload["policy_config_handoff"]["kind"] == "ptcli.site_policy_config_handoff"
    assert payload["policy_config_handoff"]["ready"] is True
    assert payload["policy_config_handoff"]["action"] == "ready_for_live_preflight"
    assert payload["policy_config_handoff"]["manual_review_required"] is False
    assert payload["policy_config_handoff"]["recommended_tool"] == "readiness_bundle"
    assert payload["policy_config_handoff"]["next_step"]["request"] == {"accept_rules": True, "source_tracker": "U2", "target": "MTEAM"}
    assert payload["policy_gap_summary"]["by_role"]["source"]["trackers"] == ["U2"]
    assert payload["policy_gap_summary"]["by_role"]["target"]["trackers"] == ["MTEAM"]


