def test_agent_run_preview_exposes_closure_walkthrough() -> None:
    blocked = ptcli_service.agent_run_preview_payload({"source_url": "https://u2.dmhy.org/details.php?id=60635", "target": "MTEAM"})
    assert blocked["status"] == "blocked"
    assert blocked["dry_run"] is True
    assert blocked["mutates_state"] is False
    assert "accept_rules=true is required before live retorrent automation." in blocked["blockers"]
    assert blocked["recommended_tool"] == "source_url_retorrent_preflight"
    assert blocked["next_step"]["endpoint"] == "/v1/retorrent/source-url/preflight"
    assert blocked["closure_contract"]["primary_field"] == "closure_handoff"
    assert blocked["closure_contract"]["control_field"] == "job_control_summary"
    assert blocked["closure_handoff_examples"]["resume"]["closure_handoff"]["recommended_tool"] == "resume_job"

    ready = ptcli_service.agent_run_preview_payload(
        {
            "source_url": "https://u2.dmhy.org/details.php?id=60635",
            "target": "MTEAM",
            "accept_rules": True,
            "confirm_upload": True,
            "save_path": "/downloads",
            "uploaded_qbit_category": "MTEAM",
        }
    )
    assert ready["status"] == "ok"
    assert ready["request_template"]["source_url"] == "https://u2.dmhy.org/details.php?id=60635"
    assert ready["request_template"]["target"] == "MTEAM"
    assert ready["request_template"]["save_path"] == "/downloads"
    assert ready["one_call_handoff"]["ready"] is True
    assert ready["one_call_handoff"]["tool"] == "source_url_check_and_submit"
    assert ready["one_call_handoff"]["endpoint"] == "/v1/jobs/retorrent/from-url/check-and-submit"
    assert ready["recommended_tool"] == "source_url_check_and_submit"
    assert [step["tool"] for step in ready["steps"]] == ["source_url_retorrent_preflight", "readiness_bundle", "site_policies", "retorrent_check", "source_url_retorrent_job", "get_job_status", "metadata_prepare_job", "materials_prepare_job", "target_package_prepare_job", "target_upload_job", "get_job_summary"]
    assert "policy_execution_summary" in ready["steps"][0]["read"]
    assert "policy_execution_handoff" in ready["steps"][0]["read"]
    assert "live_readiness.policy_execution_summary" in ready["steps"][1]["read"]
    assert "live_readiness.policy_execution_handoff" in ready["steps"][1]["read"]
    assert "policy_execution_handoff.ready" in ready["steps"][2]["read"]
    assert ready["steps"][2]["continue_when"] == "ready=true and policy_execution_handoff.ready=true"
    assert ready["steps"][3]["tool"] == "retorrent_check"
    assert ready["steps"][3]["request"]["source"] == ready["request_template"]["source_url"]
    assert ready["steps"][4]["request"] == ready["request_template"]
    assert "job_handoff" in ready["steps"][4]["read"]
    assert "job_handoff.action" in ready["steps"][5]["read"]
    assert ready["steps"][5]["repeat_when"] == "job_handoff.action=wait and job_handoff.should_poll=true"
    assert ready["steps"][6]["tool"] == "metadata_prepare_job"
    assert "metadata_prepare_handoff.material_options" in ready["steps"][6]["read"]
    assert "metadata_prepare_handoff.next_step" in ready["steps"][6]["read"]
    assert ready["steps"][7]["tool"] == "materials_prepare_job"
    assert "materials_prepare_handoff.material_options" in ready["steps"][7]["read"]
    assert "materials_prepare_handoff.next_step" in ready["steps"][7]["read"]
    assert ready["steps"][8]["tool"] == "target_package_prepare_job"
    assert "target_package_handoff.package_dir" in ready["steps"][8]["read"]
    assert "target_package_handoff.target_upload_request" in ready["steps"][8]["read"]
    assert ready["steps"][9]["tool"] == "target_upload_job"
    assert "target_upload_handoff.uploaded_seeding_ready" in ready["steps"][9]["read"]
    assert ready["steps"][10]["complete_when"] == "live_user_report.report_allowed=true"
    assert ready["steps"][10]["resume_with"].startswith("job_handoff")
    assert "source_url_check_and_submit" in ready["next_actions"][0]

    daily_blocked = ptcli_service.agent_run_preview_payload({"workflow": "daily_candidates", "source_tracker": "U2", "target": "MTEAM", "accept_rules": True})
    assert daily_blocked["workflow"] == "daily_candidates"
    assert daily_blocked["status"] == "blocked"
    assert "confirm_upload=true will be required before submitting an approved candidate." in daily_blocked["blockers"]
    assert "save_path or path will be required before submitting an approved candidate." in daily_blocked["blockers"]

    daily_ready = ptcli_service.agent_run_preview_payload(
        {
            "workflow": "daily_candidates",
            "source_tracker": "U2",
            "target": "MTEAM",
            "accept_rules": True,
            "confirm_upload": True,
            "save_path": "/downloads",
            "uploaded_qbit_category": "MTEAM",
        }
    )
    assert daily_ready["status"] == "ok"
    assert daily_ready["request_template"]["source_tracker"] == "U2"
    assert daily_ready["request_template"]["submission_overrides"]["confirm_upload"] is True
    assert [step["tool"] for step in daily_ready["steps"]] == ["readiness_bundle", "daily_candidates_schedule_job", "submit_daily_candidate_job"]
    assert daily_ready["steps"][1]["request"]["schedules"][0]["source_tracker"] == "U2"
    assert daily_ready["steps"][2]["request"]["overrides"]["save_path"] == "/downloads"
    assert "Create daily candidate schedule jobs" in daily_ready["next_actions"][0]


def test_agent_manifest_exposes_ai_safe_workflows() -> None:
    manifest = ptcli_service.agent_manifest_payload(base_url="http://ptcli.local:8080")

    assert manifest["schema_version"] == "ptcli.agent_manifest.v1"
    assert manifest["base_url"] == "http://ptcli.local:8080"
    assert manifest["discovery"]["openapi"] == "http://ptcli.local:8080/openapi.json"
    assert manifest["discovery"]["goal_progress"] == "http://ptcli.local:8080/v1/goal/progress"
    assert manifest["discovery"]["deployment_check"] == "http://ptcli.local:8080/v1/deployment/check"
    assert manifest["discovery"]["source_url_preflight"] == "http://ptcli.local:8080/v1/retorrent/source-url/preflight"
    assert manifest["discovery"]["readiness_bundle"] == "http://ptcli.local:8080/v1/readiness/bundle"
    assert manifest["discovery"]["site_policy_rule_review"] == "http://ptcli.local:8080/v1/site-policies/rule-review"
    assert manifest["discovery"]["summary_check"] == "http://ptcli.local:8080/v1/summary/check"
    assert manifest["discovery"]["materials_prepare"] == "http://ptcli.local:8080/v1/materials/prepare"
    assert manifest["discovery"]["materials_prepare_job"] == "http://ptcli.local:8080/v1/jobs/materials/prepare"
    assert manifest["discovery"]["metadata_prepare"] == "http://ptcli.local:8080/v1/metadata/prepare"
    assert manifest["discovery"]["metadata_prepare_job"] == "http://ptcli.local:8080/v1/jobs/metadata/prepare"
    assert manifest["discovery"]["target_package_prepare"] == "http://ptcli.local:8080/v1/target/package/prepare"
    assert manifest["discovery"]["target_package_prepare_job"] == "http://ptcli.local:8080/v1/jobs/target/package/prepare"
    assert manifest["discovery"]["target_upload_preflight"] == "http://ptcli.local:8080/v1/target/upload/preflight"
    assert manifest["discovery"]["target_upload"] == "http://ptcli.local:8080/v1/target/upload"
    assert manifest["discovery"]["target_upload_job"] == "http://ptcli.local:8080/v1/jobs/target/upload"
    assert manifest["auth"]["env"] == "PTCLI_API_TOKEN"
    assert "accept_rules=true" in manifest["safety"]["live_upload_requires"]
    assert "confirm_upload=true" in manifest["safety"]["live_upload_requires"]
    assert manifest["skill_contract"]["primary_entrypoints"]["manual_source_url_retorrent"]["tool"] == "source_url_check_and_submit"
    assert "deployment_check" in manifest["skill_contract"]["mandatory_preflight"]
    assert "goal_progress" in manifest["skill_contract"]["mandatory_preflight"]
    assert "live_user_report.report_allowed=true" in manifest["skill_contract"]["completion_evidence"]
    assert "seedbox_live_validation_completion_report.ready_for_user_report=true" in manifest["skill_contract"]["completion_evidence"]
    assert "Ask for explicit user confirmation before setting accept_rules=true or confirm_upload=true when it was not already supplied by the user." in manifest["agent_instructions"]["must"]
    assert "Do not bypass site_policies, rule_obligations, policy_execution_handoff, or duplicate_check." in manifest["agent_instructions"]["must_not"]
    assert "site policy config_audit reports missing_fields or placeholder_fields" in manifest["agent_instructions"]["ask_user_when"]
    assert manifest["tool_selection"]["manual_link_to_target"] == "source_url_check_and_submit"
    assert manifest["tool_selection"]["rules_and_rate_limits"] == "site_policies"
    assert manifest["closure_contract"]["primary_field"] == "closure_handoff"
    assert manifest["closure_contract"]["control_field"] == "job_control_summary"
    assert manifest["closure_contract"]["final_report_field"] == "live_user_report"
    assert manifest["closure_contract"]["complete_when"] == "live_user_report.report_allowed=true"
    assert manifest["closure_contract"]["live_validation_report_field"] == "seedbox_live_validation_completion_report"
    assert manifest["closure_contract"]["next_step_source"].startswith("job_control_summary")
    assert manifest["closure_contract"]["actions"]["repair_qbit"].startswith("Use closure_handoff.next_step")
    assert {tool["name"] for tool in manifest["tools"]} >= {"agent_run_preview", "source_url_retorrent_preflight", "goal_progress", "deployment_check", "readiness_bundle", "summary_check", "materials_prepare", "materials_prepare_job", "metadata_prepare", "metadata_prepare_job", "target_package_prepare", "target_upload_preflight", "target_upload", "target_package_prepare_job", "target_upload_job", "site_profiles", "site_policies", "site_policy_rule_review", "qbit_inspect", "qbit_match", "qbit_export_target_torrent", "qbit_inject_torrent", "qbit_wait_complete", "source_url_check_and_submit", "source_url_retorrent_job", "manual_retorrent_job", "retorrent_job", "retorrent_check_job", "submit_checked_retorrent_job", "daily_candidates_job", "submit_daily_candidate_job", "daily_candidates_schedule_job", "list_jobs", "get_job_status", "get_job_summary", "resume_job", "cancel_job"}
