    assert "closure_summary.next_step" in source_url_workflow["runbook"][10]["read"]
    assert source_url_workflow["runbook"][10]["complete_when"] == "live_user_report.report_allowed=true"
    assert source_url_workflow["runbook"][10]["resume_with"].startswith("job_handoff")
    manual_workflow = next(workflow for workflow in manifest["default_workflows"] if workflow["name"] == "manual_retorrent")
    assert manual_workflow["tool"] == "manual_retorrent_job"
    assert manual_workflow["runbook_ref"] == "source_url_retorrent"
    daily_workflow = next(workflow for workflow in manifest["default_workflows"] if workflow["name"] == "daily_candidates")
    assert daily_workflow["tool"] == "daily_candidates_schedule_job"
    assert daily_workflow["runbook"][2]["tool"] == "submit_daily_candidate_job"
    retorrent_tool = next(tool for tool in manifest["tools"] if tool["name"] == "retorrent_job")
    assert retorrent_tool["input_schema"]["required"] == ["source", "target"]
    assert "uploaded_qbit_upload_limit" in retorrent_tool["input_schema"]["properties"]
    assert "resume_state" in retorrent_tool["response_contract"]["required_fields"]
    assert "resume_plan" in retorrent_tool["response_contract"]["required_fields"]
    assert "resume_lineage" in retorrent_tool["response_contract"]["required_fields"]
    assert "agent_decision" in retorrent_tool["response_contract"]["required_fields"]
    assert "confirm_upload=true" in retorrent_tool["safety"]["requires_confirmation"]
    assert manifest["openclaw"]["manifest_url"] == "http://ptcli.local:8080/v1/openclaw/skill.json"
    assert manifest["hermes"]["manifest_url"] == "http://ptcli.local:8080/v1/hermes/skill.json"


