def test_readiness_bundle_blocks_live_when_credentials_and_image_host_are_missing(tmp_path, monkeypatch) -> None:
    (tmp_path / "data" / "cookies").mkdir(parents=True)
    (tmp_path / "tmp").mkdir()
    (tmp_path / "jobs").mkdir()
    (tmp_path / "downloads").mkdir()
    (tmp_path / "data" / "config.py").write_text("config = {}", encoding="utf-8")
    config = {
        "DEFAULT": {"default_torrent_client": "qbittorrent"},
        "TORRENT_CLIENTS": {"qbittorrent": {"torrent_client": "qbit", "qbit_url": "http://host.docker.internal", "qbit_port": "8080"}},
        "TRACKERS": {"U2": {}, "MTEAM": {}},
        "PTCLI": {
            "SITE_POLICIES": {
                "U2": {"allow_auto_download": True, "allow_retorrent": True, "rule_review_fingerprint": "u2-review"},
                "MTEAM": {"allow_auto_upload": True, "allow_retorrent": True, "rule_review_fingerprint": "mteam-review"},
            }
        },
    }
    monkeypatch.setattr(ptcli_service, "load_config", lambda _path=None: config)
    monkeypatch.setenv("TMPDIR", str(tmp_path / "tmp"))

    payload = ptcli_service.readiness_bundle_payload(
        {
            "base_dir": str(tmp_path),
            "job_dir": str(tmp_path / "jobs"),
            "downloads_path": str(tmp_path / "downloads"),
            "source_tracker": "U2",
            "source_id": "60635",
            "target": "MTEAM",
            "accept_rules": True,
            "confirm_upload": True,
        }
    )

    assert payload["live_verification"]["ready"] is False
    assert payload["live_readiness"]["ready_for_manual_retorrent"] is False
    assert payload["live_readiness"]["policy_execution_summary"]["ready"] is False
    assert payload["live_readiness"]["policy_execution_handoff"]["ready"] is False
    assert {"tracker": "U2", "field": "download_rate_limit"} in payload["live_readiness"]["policy_execution_summary"]["qbit_limit_plan"]["missing"]
    assert {"tracker": "U2", "field": "download_rate_limit"} in payload["live_readiness"]["policy_execution_handoff"]["qbit"]["missing"]
    assert payload["live_validation_repair_plan"]["ready"] is False
    assert "docker_compose_api" in payload["live_validation_repair_plan"]["blocked_categories"]
    assert "site_policy" in payload["live_validation_repair_plan"]["blocked_categories"]
    assert "credentials_and_materials" in payload["live_validation_repair_plan"]["blocked_categories"]
    assert payload["live_validation_repair_plan"]["next_step"]["tool"] == "deployment_check"
    assert {"tracker": "MTEAM", "field": "upload_rate_limit"} in payload["live_readiness"]["policy_execution_summary"]["qbit_limit_plan"]["missing"]
    check_names = {check["name"] for check in payload["live_verification"]["checks"] if check["ok"] is False}
    assert {"U2.passkey", "U2.cookie", "MTEAM.api_key", "materials.image_host"} <= check_names
    assert any("TRACKERS.MTEAM.api_key" in action for action in payload["next_actions"])
    assert any("data/cookies/<TRACKER>.txt" in action for action in payload["next_actions"])
    assert payload["live_test_handoff"]["next_step"]["reason"] == "site_policy_not_ready"


def test_parse_recent_candidate_seeds_from_nexusphp_html() -> None:
    html = """
    <table>
      <tr>
        <td><a href="details.php?id=60635" title="Example.Release.2024.1080p">Example</a></td>
        <td>42.5 GiB</td><td>2026-07-02 10:00</td><td>Free 2X</td><td>Seeders 12</td><td>Leechers 3</td>
      </tr>
      <tr><td><a href="/details.php?id=60636">Second.Release.2024</a></td><td>12 GB</td></tr>
    </table>
    """

    seeds = ptcli_candidates.parse_recent_candidate_seeds("U2", html, base_url="https://u2.dmhy.org", limit=10)

    assert len(seeds) == 2
    assert seeds[0].tracker == "U2"
    assert seeds[0].torrent_id == "60635"
    assert seeds[0].title == "Example.Release.2024.1080p"
    assert seeds[0].details_url == "https://u2.dmhy.org/details.php?id=60635"
    assert seeds[0].size == "42.5 GiB"
    assert seeds[0].published_at == "2026-07-02 10:00"
    assert seeds[0].promotion == "free,2x"


def test_candidate_request_context_caps_limit_and_defaults() -> None:
    context = ptcli_service._candidate_request_context({"source_tracker": "U2", "target": "MTEAM", "limit": 99})

    assert context["source_tracker"] == "U2"
    assert context["target_trackers"] == "MTEAM"
    assert context["limit"] == 10
    assert context["check_dupes"] is True


async def test_daily_candidates_reports_missing_cookie_blocker(tmp_path) -> None:
    result = await ptcli_candidates.build_daily_candidates(
        {"TRACKERS": {"MTEAM": {"api_key": "fake"}}},
        "U2",
        "MTEAM",
        limit=10,
        base_dir=str(tmp_path),
        accept_rules=False,
    )

    assert result["status"] == "blocked"
    assert result["count"] == 0
    assert any("cookie file is required" in blocker for blocker in result["blockers"])
    assert any("rules" in blocker.lower() or "acknowledge" in blocker.lower() for blocker in result["blockers"])


async def test_daily_candidates_builds_ready_candidate(monkeypatch) -> None:
    seed = ptcli_candidates.CandidateSeed("U2", "60635", "Example.Release", "https://u2.dmhy.org/details.php?id=60635", size="42 GiB", promotion="free")

    async def fake_fetch_recent_candidate_seeds(*_args, **_kwargs):
        return [seed]

    async def fake_fetch_source_info(*_args, **_kwargs):
        return source_info_from_tuple("U2", "60635", (1234567, 999, "Example.Release", "a" * 40, "desc"), {})

    async def fake_search_mteam_duplicates(_config, source_info):
        return {"searched": True, "count": 0, "dupes": [], "query": {"imdb": f"tt{source_info['imdb_id']}"}}

    monkeypatch.setattr(ptcli_candidates, "fetch_recent_candidate_seeds", fake_fetch_recent_candidate_seeds)
    monkeypatch.setattr(ptcli_candidates, "fetch_source_info", fake_fetch_source_info)
    monkeypatch.setattr(ptcli_candidates, "search_mteam_duplicates", fake_search_mteam_duplicates)

    config = {
        "TRACKERS": {"MTEAM": {"api_key": "fake"}},
        "PTCLI": {
            "SITE_POLICIES": {
                "MTEAM": {"upload_rate_limit": "2MiB/s", "min_ratio": 1.0, "rule_review_fingerprint": "mteam-review"},
                "U2": {"download_rate_limit": "20MiB/s", "min_seed_time_hours": 72, "rule_review_fingerprint": "u2-review"},
            }
        },
    }
    result = await ptcli_candidates.build_daily_candidates(config, "U2", "MTEAM", limit=1, accept_rules=True)

    assert result["status"] == "ok"
    assert result["target_count"] == 1
    assert result["scan_count"] == 1
    assert result["count"] == 1
    assert result["ready_count"] == 1
    assert result["shortfall_count"] == 0
    assert result["target_met"] is True
    assert result["target_summary"]["ready_target_met"] is True
    assert result["ranking"]["scan_count"] == 1
    assert result["ranking"]["selected_count"] == 1
    assert result["digest"]["recommendation"] == "submit_top_candidate_when_confirmed"
    assert result["digest"]["target_count"] == 1
    assert result["digest"]["target_met"] is True
    assert result["digest"]["shortfall_count"] == 0
    assert result["digest"]["push_summary"] == "1/1 candidate(s): 1 ready, 0 need review, 0 blocked. Recommendation: submit_top_candidate_when_confirmed."
    assert result["digest"]["push_payload"]["kind"] == "ptcli.daily_candidates_push_payload"
    assert result["digest"]["push_payload"]["target_count"] == 1
    assert result["digest"]["push_payload"]["shortfall_count"] == 0
    assert result["digest"]["push_payload"]["target_met"] is True
    assert result["digest"]["push_payload"]["ready_count"] == 1
    assert result["digest"]["push_payload"]["top_item"]["source_id"] == "60635"
    candidate_report = result["digest"]["daily_candidate_report"]
    assert candidate_report["kind"] == "ptcli.daily_candidate_report"
    assert candidate_report["scope"] == "single_schedule"
    assert candidate_report["decision"] == "submit_ready"
    assert candidate_report["target_count"] == 1
    assert candidate_report["selected_count"] == 1
    assert candidate_report["ready_count"] == 1
    assert candidate_report["safe_to_submit_count"] == 1
    assert candidate_report["ready_shortfall_count"] == 0
    assert candidate_report["target_met"] is True
    assert candidate_report["ready_target_met"] is True
    assert candidate_report["submission_ready"] is True
    assert candidate_report["recommended_tool"] == "submit_daily_candidate_job"
