    assert plan["ready"] is False
    assert plan["target_count"] == 10
    assert plan["ready_count"] == 1
    assert plan["ready_shortfall_count"] == 9
    assert plan["request_context"] == {
        "source_tracker": "U2",
        "target_trackers": ["MTEAM"],
        "target": "MTEAM",
        "limit": 10,
        "accept_rules": True,
        "check_dupes": True,
    }
