        {"stage": "match", "ok": True, "result": {"count": 1, "matches": [{"content_path": str(content_path), "hash": "a" * 40}]}},
        {"stage": "target-dupe-check", "ok": True, "result": {"searched": True, "count": 0, "dupes": []}},
