    uploaded_torrent.write_bytes(b"d4:infod")
    config = {
        "DEFAULT": {"default_torrent_client": "qbittorrent"},
        "TRACKERS": {"U2": {"passkey": "u2-passkey"}, "MTEAM": {"api_key": "mteam-api"}},
        "TORRENT_CLIENTS": {"qbittorrent": {"torrent_client": "qbit"}},
        **READY_REFERENCE_POLICY_CONFIG,
    }
    source_info = {
        "tracker": "U2",
        "torrent_id": "60635",
        "name": "Name.2024.1080p.WEB-DL-GROUP",
        "imdb_id": 1234567,
        "tmdb_id": None,
        "douban_id": None,
        "douban_url": None,
        "torrenthash": "a" * 40,
        "description_length": 100,
    }
    package = write_material_ready_mteam_package(source_info, tmp_path, content_path=str(content_path), output_dir=str(tmp_path / "target"))

    payload = build_doctor_check(
        config,
        source_tracker="U2",
        source_id="60635",
        target_trackers="MTEAM",
        client="default",
        base_dir=str(tmp_path),
        content_path=str(content_path),
        package_dir=package["package_dir"],
        uploaded_torrent_file=str(uploaded_torrent),
        accept_rules=True,
        target_execute=True,
        confirm_upload=True,
        inject_uploaded_torrent=True,
        uploaded_save_path=str(content_path),
        wait_uploaded_complete=True,
    )

    uploaded_check = next(check for check in payload["checks"] if check["name"] == "uploaded_torrent_file")
    assert payload["ready"] is False
    assert payload["live_safe_to_attempt"] is False
    assert uploaded_check["ok"] is False
    assert uploaded_check["path"] == str(uploaded_torrent)
    assert uploaded_check["metadata_readable"] is False
    assert "Torrent metadata is not readable" in uploaded_check["message"]
    assert any("Fix uploaded_torrent_file" in action for action in payload["next_actions"])

    args = ptcli_cli.build_parser().parse_args(
        [
            "doctor",
            "--from",
            "U2",
            "--source-id",
            "60635",
            "--to",
            "MTEAM",
            "--base-dir",
            str(tmp_path),
            "--path",
            str(content_path),
            "--package-dir",
            package["package_dir"],
            "--accept-rules",
            "--target-execute",
            "--confirm-upload",
            "--uploaded-torrent-file",
            str(uploaded_torrent),
            "--inject-uploaded-torrent",
            "--uploaded-save-path",
            str(content_path),
            "--wait-uploaded-complete",
            "--json",
        ]
    )
    summary_payload = ptcli_cli._doctor_summary_payload(payload, args, str(tmp_path / "ptcli-doctor-summary.json"))
    artifact = summary_payload["artifacts"]["uploaded_torrent_file"]
    assert artifact["path"] == str(uploaded_torrent)
    assert artifact["exists"] is True
    assert artifact["is_file"] is True
    assert artifact["size_bytes"] > 0
    assert len(artifact["sha1"]) == 40
    assert artifact["metadata_readable"] is False
    assert artifact["doctor_check_ok"] is False
    assert "Torrent metadata is not readable" in artifact["doctor_check_message"]
    assert summary_payload["resume_state"]["artifacts"]["uploaded_torrent_file"] is False


