    await asyncio.to_thread(metadata_file.write_text, json.dumps({"tmdb_id": 999, "tmdb_type": "movie", "douban_id": "1291546"}), encoding="utf-8")
    mediainfo = tmp_path / "MI_FULL_00.txt"
