    cookies_dir = tmp_path / "data" / "cookies"
    cookies_dir.mkdir(parents=True)
    (cookies_dir / "U2.txt").write_text("uid=1;", encoding="utf-8")
    source_hash = "a" * 40
    source_info = {
        "tracker": "U2",
        "torrent_id": "60635",
        "name": "Name.2024.1080p.WEB-DL-GROUP",
        "imdb_id": 1234567,
        "tmdb_id": 2,
        "douban_id": None,
        "douban_url": None,
        "torrenthash": source_hash,
        "description_length": 4,
    }
