    assert shell_fields["PTCLI_MATERIAL_METADATA_SOURCES"] == "source"
    assert shell_fields["PTCLI_MATERIAL_METADATA_PTGEN_READY"] == "1"
    assert shell_fields["PTCLI_MATERIAL_METADATA_PTGEN_REQUIRED"] == "1"
