def test_mteam_upload_preflight_exposes_missing_description_external_id(tmp_path) -> None:
    mediainfo = tmp_path / "MI_FULL_00.txt"
    mediainfo.write_text("General\nComplete name : Example.mkv\n", encoding="utf-8")
