def test_mteam_upload_preflight_blocks_stale_mediainfo_excerpt(tmp_path) -> None:
    mediainfo = tmp_path / "MI_FULL_00.txt"
    mediainfo.write_text("General\nComplete name : Current.mkv\nDuration : 01:23:45\n", encoding="utf-8")
    screenshot = tmp_path / "screen-1.png"
    screenshot.write_bytes(b"png")
    image_host_file = tmp_path / "image-host-uploads.json"
    image_host_file.write_text(
        json.dumps({"items": [image_host_item_for_screenshot(screenshot, raw_url="https://img.example/raw.png", img_url="https://img.example/thumb.png", web_url="https://img.example/page")]}),
        encoding="utf-8",
    )
    source_info = {
        "tracker": "U2",
        "torrent_id": "60635",
        "name": "Example.Movie.2024.1080p.WEB-DL-GROUP",
        "imdb_id": 1234567,
        "tmdb_id": 999,
        "douban_id": "1291546",
        "douban_url": "https://movie.douban.com/subject/1291546/",
        "torrenthash": "a" * 40,
        "description_length": 100,
        "ptgen_description": "◎译　　名　示例电影\n◎简　　介　示例简介",
    }
    package = write_mteam_prepare_package(
        source_info,
        ["MTEAM"],
        mteam_ready_stages(),
        "/downloads/Example",
        str(tmp_path),
        accept_rules=True,
        material_files={"mediainfo_file": str(mediainfo), "screenshot_files": [str(screenshot)], "image_host_file": str(image_host_file)},
    )
    description_path = Path(package["files"]["description_draft"])
    description = description_path.read_text(encoding="utf-8")
    current_excerpt = mediainfo.read_text(encoding="utf-8").strip()
    description_path.write_text(description.replace(current_excerpt, "General\nComplete name : Stale.mkv\nDuration : 00:00:01"), encoding="utf-8")
    torrent_file = make_mteam_safe_torrent(tmp_path, "upload")

    preflight = build_mteam_upload_preflight(package["package_dir"], execute=True, torrent_file=str(torrent_file))

    assert preflight["status"] == "blocked"
    blockers = preflight["upload_payload"]["blockers"]
    assert any("materials.description.mediainfo_or_bdinfo" in blocker and str(mediainfo) in blocker for blocker in blockers)
    assert "description.mediainfo_or_bdinfo" in preflight["upload_payload"]["recovery_missing"]
    review = preflight["upload_payload"]["review"]
    assert review["description"]["has_mediainfo_or_bdinfo"] is True
    assert review["description"]["evidence"]["mediainfo_or_bdinfo"] == {
        "ready": False,
        "source": str(mediainfo),
        "length": len(mediainfo.read_text(encoding="utf-8")),
        "description_excerpt_matched": False,
    }
    assert review["description"]["evidence"]["media_info_chain"] == {
        "ready": False,
        "material_source": str(mediainfo),
        "material_length": len(mediainfo.read_text(encoding="utf-8")),
        "description_has_excerpt": True,
        "description_excerpt_matched": False,
        "payload_source": str(mediainfo),
        "payload_length": len(mediainfo.read_text(encoding="utf-8")),
    }
    audit = ptcli_cli._target_preparation_audit(package, str(torrent_file))
    assert audit["description_ready"] is False
    assert "materials.description.mediainfo_or_bdinfo" in audit["description"]["missing"]


def test_mteam_upload_preflight_blocks_stale_ptgen_description(tmp_path) -> None:
    package = write_material_ready_mteam_package(
        {
            "tracker": "U2",
            "torrent_id": "60635",
            "name": "Example.Movie.2024.1080p.WEB-DL-GROUP",
            "imdb_id": 1234567,
            "tmdb_id": 999,
            "douban_id": "1291546",
            "douban_url": "https://movie.douban.com/subject/1291546/",
            "torrenthash": "a" * 40,
            "description_length": 100,
            "ptgen_description": "◎译　　名　当前标题\n◎简　　介　当前简介",
        },
        tmp_path,
    )
    description_path = Path(package["files"]["description_draft"])
    description = description_path.read_text(encoding="utf-8")
    current_ptgen = package["materials"]["metadata"]["ptgen_description_text"]
    description_path.write_text(description.replace(current_ptgen, "◎译　　名　旧标题\n◎简　　介　旧简介"), encoding="utf-8")
    torrent_file = make_mteam_safe_torrent(tmp_path, "upload")

    preflight = build_mteam_upload_preflight(package["package_dir"], execute=True, torrent_file=str(torrent_file))

    assert preflight["status"] == "blocked"
    blockers = preflight["upload_payload"]["blockers"]
    assert any("materials.description.ptgen_description" in blocker and "does not match current metadata.ptgen_description" in blocker for blocker in blockers)
    assert "description.ptgen_description" in preflight["upload_payload"]["recovery_missing"]
    assert "metadata.ptgen_description" not in preflight["upload_payload"]["recovery_missing"]
    review = preflight["upload_payload"]["review"]
    expected_sha1 = hashlib.sha1(current_ptgen.encode("utf-8")).hexdigest()
    assert review["description"]["has_ptgen_description"] is True
    assert review["description"]["evidence"]["ptgen_description"] == {
        "ready": False,
        "length": len(current_ptgen),
        "source": "metadata.ptgen_description",
        "sha1": expected_sha1,
        "description_matched": False,
    }
    assert review["description"]["evidence"]["ptgen_chain"] == {
        "ready": False,
        "source_length": len(current_ptgen),
        "source_sha1": expected_sha1,
        "description_has_ptgen": True,
        "description_matched": False,
    }
    assert ptcli_cli._description_chain_recovery_missing("ptgen_chain", review["description"]["evidence"]["ptgen_chain"]) == ["description.ptgen_description"]
    audit = ptcli_cli._target_preparation_audit(package, str(torrent_file))
    assert audit["description_ready"] is False
    assert "materials.description.ptgen_description" in audit["description"]["missing"]


def test_mteam_upload_preflight_execute_blocks_missing_image_host_urls_in_description(tmp_path) -> None:
    mediainfo = tmp_path / "MI_FULL_00.txt"
    mediainfo.write_text("General\nComplete name : Example.mkv\n", encoding="utf-8")
    screenshots = []
    for index in (1, 2):
        screenshot = tmp_path / f"screen-{index}.png"
        screenshot.write_bytes(b"png")
        screenshots.append(str(screenshot))
    image_host_file = tmp_path / "image-host-uploads.json"
    image_host_file.write_text(
        json.dumps(
            {
                "items": [
                    image_host_item_for_screenshot(screenshots[0], raw_url="https://img.example/raw-1.png", img_url="https://img.example/thumb-1.png", web_url="https://img.example/page-1"),
                    image_host_item_for_screenshot(screenshots[1], raw_url="https://img.example/raw-2.png", img_url="https://img.example/thumb-2.png", web_url="https://img.example/page-2"),
                ]
            }
        ),
        encoding="utf-8",
    )
    source_info = {
        "tracker": "U2",
        "torrent_id": "60635",
        "name": "Example.Movie.2024.1080p.WEB-DL-GROUP",
        "imdb_id": 1234567,
        "tmdb_id": 999,
        "douban_id": "1291546",
        "douban_url": "https://movie.douban.com/subject/1291546/",
        "torrenthash": "a" * 40,
        "description_length": 100,
        "ptgen_description": "◎译　　名　示例电影\n◎简　　介　示例简介",
    }
    package = write_mteam_prepare_package(
        source_info,
        ["MTEAM"],
        mteam_ready_stages(),
        "/downloads/Example",
        str(tmp_path),
        accept_rules=True,
        material_files={"mediainfo_file": str(mediainfo), "screenshot_files": screenshots, "image_host_file": str(image_host_file)},
    )
    package_from_disk = load_mteam_prepare_package(package["package_dir"])
    description_path = Path(package_from_disk["files"]["description_draft"])
    description_text = description_path.read_text(encoding="utf-8")
    description_path.write_text(description_text.replace("[url=https://img.example/page-2][img]https://img.example/thumb-2.png[/img][/url]", ""), encoding="utf-8")
    package_from_disk["description_length"] = len(description_path.read_text(encoding="utf-8"))
    manifest_path = Path(package_from_disk["files"]["manifest"])
    manifest_path.write_text(json.dumps(package_from_disk, ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    torrent_file = make_mteam_safe_torrent(tmp_path, "upload")

    preflight = build_mteam_upload_preflight(package["package_dir"], execute=True, torrent_file=str(torrent_file))

    assert preflight["status"] == "blocked"
    coverage_check = next(check for check in preflight["upload_payload"]["material_checks"] if check["name"] == "materials.description.screenshot_coverage")
    assert coverage_check["ok"] is False
    assert coverage_check["expected_urls"] == ["https://img.example/thumb-1.png", "https://img.example/thumb-2.png"]
    assert coverage_check["description_urls"] == ["https://img.example/thumb-1.png"]
    assert coverage_check["missing_urls"] == ["https://img.example/thumb-2.png"]
    blockers = preflight["upload_payload"]["blockers"]
    assert any("materials.description.screenshot_coverage" in blocker for blocker in blockers)
    review = preflight["upload_payload"]["review"]
    assert review["description"]["screenshot_coverage"] == {
        "ready": False,
        "expected_urls": ["https://img.example/thumb-1.png", "https://img.example/thumb-2.png"],
        "description_urls": ["https://img.example/thumb-1.png"],
        "missing_urls": ["https://img.example/thumb-2.png"],
    }
    assert review["description"]["evidence"]["screenshot_coverage"] == {
        "ready": False,
        "expected_count": 2,
        "description_count": 1,
        "missing_count": 1,
        "expected_urls": ["https://img.example/thumb-1.png", "https://img.example/thumb-2.png"],
        "description_urls": ["https://img.example/thumb-1.png"],
        "missing_urls": ["https://img.example/thumb-2.png"],
    }
    assert review["materials"]["image_host_urls"] == ["https://img.example/thumb-1.png", "https://img.example/thumb-2.png"]
    audit = ptcli_cli._target_preparation_audit(package_from_disk, str(torrent_file))
    assert audit["description_ready"] is False
    assert "materials.description.screenshot_coverage" in audit["description"]["missing"]
    assert audit["description"]["screenshot_coverage"] == {
        "ready": False,
        "expected_urls": ["https://img.example/thumb-1.png", "https://img.example/thumb-2.png"],
        "description_urls": ["https://img.example/thumb-1.png"],
        "missing_urls": ["https://img.example/thumb-2.png"],
    }
    assert audit["description"]["evidence"]["screenshot_coverage"]["missing_count"] == 1


